window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[341]={"id":"341","numero":341,"titre":"Hémorragie méningée non traumatique","objectifs":[{"id":"341-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l’hémorragie méningée dite sous-arachnoïdienne, spontanée et traumatique","contenu":"<p>L'<span class=\"kw-def\">hémorragie méningée</span> — ou hémorragie <span class=\"kw-def\">sous-arachnoïdienne</span> (HSA) — se définit par la présence de <span class=\"kw-clinique\">sang artériel</span> dans les <span class=\"kw-def\">espaces sous-arachnoïdiens</span>.</p>\n      <p>Les <span class=\"kw-def\">espaces sous-arachnoïdiens</span> (ESA) sont limités par la <span class=\"kw-def\">pie-mère</span> sur le versant cérébral (interne) et par l'<span class=\"kw-def\">arachnoïde</span> sur le versant externe. Ils entourent le cerveau, contiennent le <span class=\"kw-bio\">LCS</span> ainsi que des artères et des veines de gros calibre, et sont de plus grande taille à la base du crâne où ils forment les <span class=\"kw-def\">citernes de la base</span>.</p>\n      <p><strong>Distinction sémantique essentielle</strong> — deux causes à séparer :</p>\n      <ul>\n        <li><strong>HSA spontanée :</strong> <span class=\"kw-alerte\">urgence vitale</span>, secondaire à une <span class=\"kw-etio\">rupture d'anévrisme artériel intra-crânien</span> jusqu'à preuve du contraire.</li>\n        <li><strong>HSA post-traumatique :</strong> témoin de la sévérité d'un <span class=\"kw-clinique\">traumatisme crânien</span>, ne requiert pas de traitement d'<span class=\"kw-alerte\">urgence</span> spécifique.</li>\n      </ul>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Épidémiologie</span> (HSA non traumatique)</th><th>Donnée</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Incidence</span></td><td><span class=\"kw-chiffre\">10 cas / 100 000 habitants</span> (×2 au Japon et en Finlande)</td></tr>\n          <tr><td>Âge</td><td>Touche des sujets jeunes sans ATCD ; âge médian <span class=\"kw-chiffre\">55 ans</span></td></tr>\n          <tr><td>Sex-ratio</td><td>Prédominance féminine — <span class=\"kw-chiffre\">1,6 F / 1 H</span></td></tr>\n          <tr><td><span class=\"kw-def\">Mortalité</span></td><td><span class=\"kw-alerte\">40-50 %</span> globale, dont <span class=\"kw-chiffre\">10-20 %</span> de décès en pré-hospitalier</td></tr>\n        </tbody>\n      </table>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/subarachnoid-space","label":"Radiopaedia : Subarachnoid space"}]},{"id":"341-2","rang":"B","rubrique":"Étiologies","titre":"Connaître les principales causes d’hémorragies méningées et les facteurs favorisants","contenu":"<p>Trois grands cadres étiologiques se répartissent la quasi-totalité des HSA non traumatiques :</p>\n      <table >\n        <thead><tr><th>Fréquence</th><th>Catégorie</th><th>Exemples</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-chiffre\">85 %</span></td><td><span class=\"kw-etio\">Rupture d'anévrisme artériel</span></td><td>Communicante antérieure <span class=\"kw-chiffre\">40 %</span>, carotide interne <span class=\"kw-chiffre\">30 %</span>, cérébrale moyenne <span class=\"kw-chiffre\">20 %</span>, système vertébro-basilaire <span class=\"kw-chiffre\">10 %</span></td></tr>\n          <tr><td><span class=\"kw-chiffre\">10 %</span></td><td><span class=\"kw-etio\">HSA non anévrismale péri-mésencéphalique</span></td><td><strong>Diagnostic d'exclusion</strong> ; saignement peu abondant de la citerne interpédonculaire ; <span class=\"kw-def\">physiopathologie</span> méconnue ; <span class=\"kw-alerte\">bon pronostic</span>, récidive exceptionnelle</td></tr>\n          <tr><td><span class=\"kw-chiffre\">5 %</span></td><td>Causes rares</td><td>Tumeurs ; lésions inflammatoires des artères (<span class=\"kw-etio\">Behçet</span>, angéite primaire, <span class=\"kw-etio\">Wegener</span>, anévrisme mycotique) ; <span class=\"kw-etio\">MAV</span>, <span class=\"kw-clinique\">fistule</span> durale, cavernome ; <span class=\"kw-etio\">dissection artérielle</span> ; <span class=\"kw-etio\">angiopathie amyloïde</span> (HSA corticales) ; coagulopathies ; toxiques</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Anévrisme artériel intra-crânien</strong> — formation et <span class=\"kw-alerte\">rupture</span> :</p>\n      <table >\n        <thead><tr><th>Concept</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td>Définition</td><td>Perte de parallélisme de la paroi artérielle par déhiscence de la <span class=\"kw-def\">limitante élastique interne</span> → dilatation sacciforme (rarement fusiforme), <span class=\"kw-clinique\">diamètre</span> <span class=\"kw-chiffre\">&lt; 10 mm</span> dans <span class=\"kw-chiffre\">90 %</span> des cas</td></tr>\n          <tr><td>Localisations</td><td>Bifurcations artérielles des grosses artères à destinée cérébrale, situées sur le <span class=\"kw-def\">polygone de Willis</span> (dans les citernes de la base)</td></tr>\n          <tr><td>FR de formation</td><td><span class=\"kw-alerte\">HTA</span> ; <span class=\"kw-alerte\">tabac</span>, alcool ; facteurs hémodynamiques (turbulence rhéologique aux bifurcations)</td></tr>\n          <tr><td><span class=\"kw-def\">Physiopathologie</span></td><td>Paroi anévrismale plus fragile qu'une artère saine → fissuration possible, puis <span class=\"kw-alerte\">rupture</span></td></tr>\n          <tr><td>FR de <span class=\"kw-alerte\">rupture</span></td><td>Taille <span class=\"kw-chiffre\">&gt; 10 mm</span> (risque de <span class=\"kw-alerte\">rupture</span> <span class=\"kw-chiffre\">25 %</span> si <span class=\"kw-chiffre\">&gt; 25 mm</span>) ; poussée hypertensive ; effort physique</td></tr>\n          <tr><td>Complications du saignement</td><td>Hématome intra-parenchymateux (anévrisme enchâssé) ; hémorragie intra-ventriculaire (<span class=\"kw-alerte\">rupture</span> près des ventricules) ; exceptionnellement hématome sous-dural aigu</td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-def\">Facteurs de risque</span> d'HSA</strong> :</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Facteurs</th></tr></thead>\n        <tbody>\n          <tr><td>Modifiables</td><td>\n            <ul>\n              <li><span class=\"kw-alerte\">Tabagisme</span> — FR le plus péjoratif</li>\n              <li><span class=\"kw-alerte\">HTA</span></li>\n              <li>Intoxication alcoolique chronique</li>\n            </ul>\n          </td></tr>\n          <tr><td>Non modifiables</td><td>\n            <ul>\n              <li>Sexe féminin (sex-ratio <span class=\"kw-chiffre\">1,6 F / 1 H</span>)</li>\n              <li><span class=\"kw-alerte\">ATCD familiaux d'HSA anévrismale</span> — risque majoré si <span class=\"kw-chiffre\">≥ 2 membres</span> du 1ᵉʳ degré</li>\n              <li>ATCD personnels d'anévrisme intra-crânien</li>\n              <li>Coarctation de l'aorte</li>\n              <li>Affections héréditaires du tissu conjonctif : <span class=\"kw-etio\">polykystose rénale</span> (en 1ᵉʳ lieu), NF1, Marfan, Ehlers-Danlos</li>\n            </ul>\n          </td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 266 — Polykystose rénale · 152 — Endocardite infectieuse</em></p>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/circle-of-willis","label":"Radiopaedia : Circle of willis"},{"href":"https://radiopaedia.org/articles/saccular-cerebral-aneurysm","label":"Radiopaedia : Saccular cerebral aneurysm"}]},{"id":"341-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les présentations cliniques et le diagnostic d’hémorragie méningée","contenu":"<div class=\"callout callout-danger\">\n        <strong>Dogme.</strong> Toute <span class=\"kw-clinique\">céphalée brutale</span> (&lt; <span class=\"kw-chiffre\">1 h</span>), voire en <span class=\"kw-alerte\">« coup de tonnerre »</span> (&lt; <span class=\"kw-chiffre\">1 min</span>), <span class=\"kw-clinique\">inhabituelle</span> et <span class=\"kw-clinique\">intense</span> = HSA jusqu'à preuve du contraire. Tout <span class=\"kw-clinique\">syndrome méningé non fébrile</span> = HSA jusqu'à preuve du contraire.\n      </div>\n      <p>Le tableau typique associe une <strong><span class=\"kw-clinique\">céphalée</span> brutale</strong> et un <strong><span class=\"kw-alerte\">syndrome méningé</span></strong>, sans <span class=\"kw-clinique\">fièvre</span>.</p>\n      <table >\n        <thead><tr><th>Composante</th><th>Sémiologie</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Céphalée</span> (quasi-constante)</td><td><strong>Caractères :</strong> précoce, récente, inhabituelle, mal soulagée par les <span class=\"kw-ttt\">antalgiques</span> habituels<br><strong>Topographie :</strong> en <span class=\"kw-clinique\">casque</span> ou diffuse<br><strong>Facteurs aggravants :</strong> mouvements de la tête ; examen physique ; <span class=\"kw-clinique\">photophobie</span> ; <span class=\"kw-clinique\">phonophobie</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Vomissements</span></td><td><strong>Caractères :</strong> en jet (ou simples <span class=\"kw-clinique\">nausées</span>), inconstants, généralement précoces<br><strong>Favorisés par :</strong> les changements de position<br><strong>Particularité :</strong> peuvent soulager la <span class=\"kw-clinique\">céphalée</span></td></tr>\n          <tr><td>Raideur méningée</td><td><strong>Attitude :</strong> en <span class=\"kw-clinique\">« chien de fusil »</span> (décubitus latéral, tête en hyperextension, membres semi-fléchis)<br><strong>Nuque :</strong> résistance invincible et douloureuse à la flexion ; rotation conservée mais augmente la <span class=\"kw-clinique\">céphalée</span><br><strong>Kernig :</strong> cuisses fléchies sur le bassin jambes étendues → la douleur force la flexion des jambes<br><strong>Brudzinski :</strong> flexion passive de la nuque → flexion des 2 membres inférieurs</td></tr>\n          <tr><td>Autres signes</td><td><strong>Signes associés :</strong> raie méningitique de Trousseau ; hyperesthésie cutanée diffuse ; <span class=\"kw-clinique\">ROT vifs</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Tableaux atypiques</strong> à connaître :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Céphalée</span> modérée mais <strong>toujours brutale</strong>, parfois plus postérieure (occipitale ou rachidienne)</li>\n        <li><span class=\"kw-clinique\">Céphalée</span> plus progressive dans les HSA de faible abondance ; céphalée parfois isolée</li>\n        <li><span class=\"kw-clinique\">Perte de connaissance initiale</span> avec récupération rapide</li>\n        <li><span class=\"kw-clinique\">Syndrome confusionnel aigu</span>, <span class=\"kw-clinique\">crise d'épilepsie généralisée</span>, voire <span class=\"kw-alerte\">état de mal</span></li>\n        <li><span class=\"kw-alerte\">Coma d'emblée</span> (<span class=\"kw-alerte\">HTIC</span> aiguë ou hydrocéphalie aiguë)</li>\n        <li><span class=\"kw-alerte\">Mort subite</span> par <span class=\"kw-alerte\">arrêt cardiaque</span> — troubles de conduction (<span class=\"kw-clinique\">bradycardie</span> extrême, bloc) liés à la décharge catécholaminergique du <span class=\"kw-clinique\">réflexe de Cushing</span></li>\n      </ul>\n      <p><strong>Signes associés évocateurs</strong> :</p>\n      <table >\n        <thead><tr><th>Signe</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Syndrome de Terson</span> (<span class=\"kw-chiffre\">20 %</span>)</td><td><strong>Mécanisme :</strong> hémorragies intra-oculaires uni- ou bilatérales (intra-vitréennes ou rétiniennes)<br><strong>Clinique :</strong> <span class=\"kw-clinique\">myodésopsies</span>, <span class=\"kw-clinique\">baisse de l'acuité visuelle</span><br><strong>Diagnostic :</strong> <span class=\"kw-imagerie\">fond d'œil</span> — hémorragies sous-hyaloïdiennes proches de la papille</td></tr>\n          <tr><td>Diplopie</td><td><strong>Mécanisme :</strong> atteinte du <span class=\"kw-clinique\">III</span> par compression d'un anévrisme volumineux de la portion supraclinoïdienne de la carotide interne (naissance de la communicante postérieure)<br><strong>Signes :</strong> <span class=\"kw-clinique\">mydriase aréactive</span>, ptosis, <span class=\"kw-clinique\">strabisme divergent</span></td></tr>\n          <tr><td>Déficit neurologique</td><td><strong>Rare en initial :</strong> signe une <span class=\"kw-alerte\">hémorragie cérébro-méningée</span> (HSA + hématome intra-parenchymateux) ou un <span class=\"kw-alerte\">vasospasme</span> (après J4)</td></tr>\n          <tr><td>Signes végétatifs (&lt; <span class=\"kw-chiffre\">24 h</span>)</td><td><strong>Cardiaques :</strong> brady- ou <span class=\"kw-clinique\">tachycardie</span>, modifications <span class=\"kw-imagerie\">ECG</span> mimant un <span class=\"kw-alerte\">IDM</span>, troubles du rythme<br><strong>Hémodynamiques :</strong> <span class=\"kw-alerte\">choc</span> avec <span class=\"kw-alerte\">OAP</span> (orage catécholaminergique → <span class=\"kw-clinique\">tako-tsubo</span>), instabilité tensionnelle<br><strong>Général :</strong> <span class=\"kw-clinique\">hyperthermie</span> retardée</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 100 — <span class=\"kw-clinique\">Céphalée</span> · 105 — Epilepsie · 343 — Etat confusionnel - trouble de conscience · 91 — Déficit neuro récent</em></p>","frequence":2},{"id":"341-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la stratégie d’exploration complémentaire devant un tableau clinique évocateur d’hémorragie méningée","contenu":"<div class=\"callout callout-info\">\n        <strong>Algorithme séquentiel.</strong> Devant une <span class=\"kw-clinique\">céphalée brutale inhabituelle</span> : <span class=\"kw-imagerie\">imagerie sans injection</span> d'abord, puis <span class=\"kw-clinique\">PL</span> si imagerie négative, puis exploration étiologique dès l'HSA confirmée.\n      </div>\n      <ol>\n        <li><span class=\"kw-imagerie\">TDM cérébrale non injectée</span> en <span class=\"kw-alerte\">urgence</span> = examen clé (sensibilité <span class=\"kw-chiffre\">95 % à J1</span>, décroît à <span class=\"kw-chiffre\">J5-J8</span>).</li>\n        <li>Si <span class=\"kw-imagerie\">TDM</span> normale + <span class=\"kw-clinique\">suspicion clinique persistante</span> → <span class=\"kw-clinique\">ponction lombaire</span>, idéalement à <span class=\"kw-chiffre\">≥ 6 h</span> du début (optimum <span class=\"kw-chiffre\">&gt; 12 h</span>). <span class=\"kw-ci\">Contre-indiquée</span> si <span class=\"kw-alerte\">hématome</span> ou <span class=\"kw-alerte\">hydrocéphalie avec effet de masse</span> au <span class=\"kw-imagerie\">scanner</span>.</li>\n        <li>Dès l'HSA confirmée (<span class=\"kw-imagerie\">TDM</span> ou PL positive) → <span class=\"kw-imagerie\">angioTDM cérébrale</span> immédiate à visée étiologique.</li>\n        <li><span class=\"kw-imagerie\">IRM cérébrale</span> = alternative de 2ᵉ intention si <span class=\"kw-imagerie\">TDM</span> négative et PL impossible (sensibilité <span class=\"kw-chiffre\">100 % les 5 premiers jours</span>).</li>\n      </ol>\n      <figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewBox=\"0 0 740 556\" role=\"img\" aria-label=\"Algorithme d'exploration devant une céphalée brutale évocatrice d'hémorragie méningée\" style=\"height:auto;display:block;border-radius:8px\">\n          <defs><marker id=\"a341algo\" markerWidth=\"9\" markerHeight=\"9\" refX=\"6.5\" refY=\"3\" orient=\"auto\"><path class=\"ah\" d=\"M0,0 L7,3 L0,6 Z\"/></marker></defs>\n          <text x=\"370\" y=\"24\" text-anchor=\"middle\" class=\"tx-title\" font-family=\"Georgia, serif\" font-size=\"14.5\" font-weight=\"700\">Stratégie d'exploration — <span class=\"kw-clinique\">céphalée</span> brutale inhabituelle</text>\n          <!-- arrows -->\n          <line x1=\"300\" y1=\"82\" x2=\"300\" y2=\"87\" class=\"ln\" stroke-width=\"1.5\" marker-end=\"url(#a341algo)\"/>\n          <line x1=\"300\" y1=\"133\" x2=\"300\" y2=\"156\" class=\"ln\" stroke-width=\"1.5\" marker-end=\"url(#a341algo)\"/>\n          <line x1=\"386\" y1=\"194\" x2=\"468\" y2=\"194\" class=\"ln\" stroke-width=\"1.5\" marker-end=\"url(#a341algo)\"/>\n          <text x=\"420\" y=\"186\" text-anchor=\"middle\" class=\"tx-green\" font-family=\"Georgia, serif\" font-size=\"10\" font-weight=\"700\">OUI</text>\n          <line x1=\"560\" y1=\"216\" x2=\"560\" y2=\"249\" class=\"ln\" stroke-width=\"1.5\" marker-end=\"url(#a341algo)\"/>\n          <line x1=\"300\" y1=\"232\" x2=\"300\" y2=\"262\" class=\"ln\" stroke-width=\"1.5\" marker-end=\"url(#a341algo)\"/>\n          <text x=\"314\" y=\"250\" text-anchor=\"middle\" class=\"tx-no\" font-family=\"Georgia, serif\" font-size=\"10\" font-weight=\"700\">NON</text>\n          <line x1=\"216\" y1=\"300\" x2=\"204\" y2=\"300\" class=\"ln\" stroke-width=\"1.5\" marker-end=\"url(#a341algo)\"/>\n          <text x=\"208\" y=\"271\" text-anchor=\"middle\" class=\"tx-no\" font-family=\"Georgia, serif\" font-size=\"10\" font-weight=\"700\">NON</text>\n          <line x1=\"300\" y1=\"338\" x2=\"300\" y2=\"369\" class=\"ln\" stroke-width=\"1.5\" marker-end=\"url(#a341algo)\"/>\n          <text x=\"314\" y=\"357\" text-anchor=\"middle\" class=\"tx-green\" font-family=\"Georgia, serif\" font-size=\"10\" font-weight=\"700\">OUI</text>\n          <line x1=\"300\" y1=\"415\" x2=\"300\" y2=\"440\" class=\"ln\" stroke-width=\"1.5\" marker-end=\"url(#a341algo)\"/>\n          <line x1=\"384\" y1=\"478\" x2=\"468\" y2=\"478\" class=\"ln\" stroke-width=\"1.5\" marker-end=\"url(#a341algo)\"/>\n          <text x=\"420\" y=\"470\" text-anchor=\"middle\" class=\"tx-green\" font-family=\"Georgia, serif\" font-size=\"10\" font-weight=\"700\">OUI</text>\n          <line x1=\"216\" y1=\"478\" x2=\"206\" y2=\"478\" class=\"ln\" stroke-width=\"1.5\" marker-end=\"url(#a341algo)\"/>\n          <text x=\"210\" y=\"449\" text-anchor=\"middle\" class=\"tx-no\" font-family=\"Georgia, serif\" font-size=\"10\" font-weight=\"700\">NON</text>\n          <path d=\"M560,457 L560,293\" fill=\"none\" class=\"ln\" stroke-width=\"1.3\" stroke-dasharray=\"4 4\" marker-end=\"url(#a341algo)\"/>\n          <!-- start -->\n          <rect x=\"200\" y=\"42\" width=\"200\" height=\"40\" rx=\"20\" class=\"fb-amber\" stroke-width=\"1.5\"/>\n          <text text-anchor=\"middle\" class=\"tx-amber\" font-family=\"Georgia, serif\" font-size=\"10.5\" font-weight=\"600\"><tspan x=\"300\" y=\"60\">Céphalée brutale inhabituelle /</tspan><tspan x=\"300\" y=\"75\">sd méningé non fébrile</tspan></text>\n          <!-- TDM -->\n          <rect x=\"200\" y=\"87\" width=\"200\" height=\"46\" rx=\"8\" class=\"fb-blue\" stroke-width=\"1.4\"/>\n          <text text-anchor=\"middle\" class=\"tx-blue\" font-family=\"Georgia, serif\" font-size=\"10.5\" font-weight=\"600\"><tspan x=\"300\" y=\"106\"><span class=\"kw-imagerie\">TDM</span> cérébrale SANS injection</tspan><tspan x=\"300\" y=\"121\">(en <span class=\"kw-alerte\">urgence</span>)</tspan></text>\n          <!-- D1 -->\n          <polygon points=\"300,156 388,194 300,232 212,194\" class=\"fb-purple\" stroke-width=\"1.4\"/>\n          <text x=\"300\" y=\"198\" text-anchor=\"middle\" class=\"tx-purple\" font-family=\"Georgia, serif\" font-size=\"10.5\">Hyperdensité des ESA ?</text>\n          <!-- HSA confirmée (D1 oui) -->\n          <rect x=\"470\" y=\"172\" width=\"180\" height=\"44\" rx=\"8\" class=\"fb-ok\" stroke-width=\"1.4\"/>\n          <text x=\"560\" y=\"198\" text-anchor=\"middle\" class=\"tx-ok\" font-family=\"Georgia, serif\" font-size=\"11\" font-weight=\"700\">HSA confirmée</text>\n          <!-- angioTDM -->\n          <rect x=\"470\" y=\"249\" width=\"180\" height=\"46\" rx=\"8\" class=\"fb-blue\" stroke-width=\"1.4\"/>\n          <text text-anchor=\"middle\" class=\"tx-blue\" font-family=\"Georgia, serif\" font-size=\"10.5\" font-weight=\"600\"><tspan x=\"560\" y=\"268\"><span class=\"kw-imagerie\">angioTDM</span> immédiate</tspan><tspan x=\"560\" y=\"283\">(visée étiologique)</tspan></text>\n          <!-- D2 -->\n          <polygon points=\"300,262 384,300 300,338 216,300\" class=\"fb-purple\" stroke-width=\"1.4\"/>\n          <text text-anchor=\"middle\" class=\"tx-purple\" font-family=\"Georgia, serif\" font-size=\"10\"><tspan x=\"300\" y=\"298\">Suspicion clinique</tspan><tspan x=\"300\" y=\"312\">persistante ?</tspan></text>\n          <!-- écartée (D2 non) -->\n          <rect x=\"24\" y=\"278\" width=\"180\" height=\"44\" rx=\"8\" class=\"fb-grey\" stroke-width=\"1.4\"/>\n          <text text-anchor=\"middle\" class=\"tx-grey\" font-family=\"Georgia, serif\" font-size=\"9.5\"><tspan x=\"114\" y=\"297\">Autre cause de céphalée</tspan><tspan x=\"114\" y=\"311\">— HSA écartée</tspan></text>\n          <!-- PL -->\n          <rect x=\"200\" y=\"369\" width=\"200\" height=\"46\" rx=\"8\" class=\"fb-teal\" stroke-width=\"1.4\"/>\n          <text text-anchor=\"middle\" class=\"tx-teal\" font-family=\"Georgia, serif\" font-size=\"10.5\" font-weight=\"600\"><tspan x=\"300\" y=\"388\"><span class=\"kw-ttt\">Ponction</span> lombaire <span class=\"kw-chiffre\">≥ 6 h</span></tspan><tspan x=\"300\" y=\"403\">(optimum &gt;<span class=\"kw-chiffre\"> 12 h</span>)</tspan></text>\n          <!-- D3 -->\n          <polygon points=\"300,440 388,478 300,516 212,478\" class=\"fb-purple\" stroke-width=\"1.4\"/>\n          <text text-anchor=\"middle\" class=\"tx-purple\" font-family=\"Georgia, serif\" font-size=\"9.5\"><tspan x=\"300\" y=\"474\">Xanthochromie /</tspan><tspan x=\"300\" y=\"488\">GR incoagulables ?</tspan></text>\n          <!-- HSA confirmée (D3 oui) -->\n          <rect x=\"470\" y=\"457\" width=\"180\" height=\"42\" rx=\"8\" class=\"fb-ok\" stroke-width=\"1.4\"/>\n          <text x=\"560\" y=\"483\" text-anchor=\"middle\" class=\"tx-ok\" font-family=\"Georgia, serif\" font-size=\"11\" font-weight=\"700\">HSA confirmée</text>\n          <!-- éliminée (D3 non) -->\n          <rect x=\"26\" y=\"455\" width=\"180\" height=\"46\" rx=\"8\" class=\"fb-grey\" stroke-width=\"1.4\"/>\n          <text text-anchor=\"middle\" class=\"tx-grey\" font-family=\"Georgia, serif\" font-size=\"9.5\"><tspan x=\"116\" y=\"474\">PL normale &gt;<span class=\"kw-chiffre\"> 12 h</span> →</tspan><tspan x=\"116\" y=\"488\">HSA fortement éliminée</tspan></text>\n          <!-- IRM note -->\n          <text x=\"468\" y=\"338\" text-anchor=\"middle\" class=\"tx-muted\" font-family=\"Georgia, serif\" font-size=\"9\" font-style=\"italic\"><span class=\"kw-imagerie\">IRM</span> = 2ᵉ intention si PL impossible (Se <span class=\"kw-chiffre\">100 %</span> à 5 j)</text>\n          <!-- CI note -->\n          <text x=\"370\" y=\"540\" text-anchor=\"middle\" class=\"tx-warn\" font-family=\"Georgia, serif\" font-size=\"9.5\" font-style=\"italic\">⚠ PL <span class=\"kw-ci\">contre-indiquée</span> si hématome ou hydrocéphalie avec effet de <span class=\"kw-clinique\">masse</span> au <span class=\"kw-imagerie\">scanner</span></text>\n        </svg>\n        <figcaption>Algorithme séquentiel : <span class=\"kw-imagerie\">TDM sans injection</span> d'abord → si normale et suspicion persistante, <span class=\"kw-clinique\">PL</span> à distance → <span class=\"kw-imagerie\">angioTDM</span> dès l'HSA confirmée. Version statique ; un arbre interactif Quiz/Explorer pourra être généré ultérieurement.</figcaption>\n      </figure>\n      <p><strong>Délais critiques de la PL</strong> :</p>\n      <table >\n        <thead><tr><th>Délai depuis la <span class=\"kw-clinique\">céphalée</span></th><th>Interprétation</th></tr></thead>\n        <tbody>\n          <tr><td>PL <span class=\"kw-chiffre\">&lt; 6 h</span></td><td>Une PL normale <span class=\"kw-alerte\">n'élimine pas</span> l'HSA — faux négatifs possibles</td></tr>\n          <tr><td>PL <span class=\"kw-chiffre\">&gt; 12 h</span></td><td>Une PL normale permet d'<strong>éliminer fortement</strong> l'HSA</td></tr>\n          <tr><td>PL <span class=\"kw-chiffre\">&gt; 2 semaines</span></td><td>Sensibilité effondrée — une PL normale <span class=\"kw-alerte\">n'élimine plus</span> l'HSA</td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"341-5","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les signes évocateurs d’hémorragie méningée au scanner cérébral sans injection","contenu":"<p>Le <span class=\"kw-imagerie\">TDM cérébral sans injection</span> est l'examen pivot du <span class=\"kw-def\">diagnostic positif</span> d'HSA, à réaliser en <span class=\"kw-alerte\">urgence</span>.</p>\n      <table >\n        <thead><tr><th>Item</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td>Signe direct</td><td><span class=\"kw-radio\">Hyperdensité spontanée</span> des <span class=\"kw-def\">espaces sous-arachnoïdiens</span></td></tr>\n          <tr><td>Localisations typiques</td><td><span class=\"kw-def\">Citernes de la base</span> ; <span class=\"kw-radio\">vallée sylvienne</span> (scissure latérale) ; <span class=\"kw-radio\">scissure interhémisphérique</span> (longitudinale) ; <span class=\"kw-radio\">sillons corticaux</span></td></tr>\n          <tr><td>Sensibilité</td><td><span class=\"kw-chiffre\">95 % à J1</span> ; décroissance progressive ; disparition de l'hyperdensité en <span class=\"kw-chiffre\">5-8 jours</span></td></tr>\n          <tr><td>Faux négatif</td><td>Une <span class=\"kw-imagerie\">TDM</span> normale <span class=\"kw-alerte\">n'élimine pas l'HSA</span> → impose une <span class=\"kw-clinique\">PL</span> ou une <span class=\"kw-imagerie\">IRM</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Orientations étiologiques au <span class=\"kw-imagerie\">TDM</span></strong> :</p>\n      <ul>\n        <li><span class=\"kw-radio\">Calcifications de la paroi anévrismale</span> (rare) = visualisation directe d'un anévrisme</li>\n        <li><span class=\"kw-imagerie\">HSA corticale</span> = doit faire suspecter une étiologie non anévrismale → <span class=\"kw-etio\">angiopathie amyloïde</span> (++), <span class=\"kw-etio\">MAV</span>, <span class=\"kw-etio\">thrombose veineuse cérébrale</span></li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> Rechercher dès le <span class=\"kw-imagerie\">TDM</span> initial les complications visibles : <span class=\"kw-alerte\">hématome intra-parenchymateux associé</span>, <span class=\"kw-alerte\">hémorragie intra-ventriculaire</span>, <span class=\"kw-alerte\">hydrocéphalie aiguë</span> (<span class=\"kw-radio\">dilatation ventriculaire</span>).\n      </div>","frequence":0},{"id":"341-6","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les caractéristiques du liquide céphalo-rachidien dans l’hémorragie méningée","contenu":"<p>La <span class=\"kw-clinique\">ponction lombaire</span> est l'examen de 2ᵉ ligne, indiquée si la <span class=\"kw-imagerie\">TDM</span> est normale mais la suspicion clinique persistante. Elle n'est <strong>jamais réalisée d'emblée</strong>. L'enjeu est de distinguer une vraie HSA d'une PL traumatique.</p>\n      <table >\n        <thead><tr><th>Paramètre</th><th>HSA</th><th>PL traumatique</th></tr></thead>\n        <tbody>\n          <tr><td>Pression</td><td>Élevée <span class=\"kw-chiffre\">&gt; 25 cm H₂O</span> (témoin d'<span class=\"kw-alerte\">HTIC</span>)</td><td>Pression d'ouverture normale</td></tr>\n          <tr><td>Couleur</td><td>Liquide <span class=\"kw-bio\">uniformément rouge / rosé</span> dans les 3 tubes</td><td>De moins en moins rouge au cours du recueil</td></tr>\n          <tr><td>Coagulabilité</td><td><span class=\"kw-bio\">Incoagulable</span></td><td>Coagulable</td></tr>\n          <tr><td>Surnageant (après centrifugation)</td><td><span class=\"kw-bio\">Xanthochromique</span> dans <span class=\"kw-chiffre\">100 %</span> des cas si PL entre <span class=\"kw-chiffre\">12 h et 14 j</span> ; pigments dès la 12ᵉ heure (<span class=\"kw-bio\">bilirubine</span>, <span class=\"kw-bio\">oxyhémoglobine</span>) ; <span class=\"kw-bio\">spectrophotométrie</span> → chromoprotéines (oxyhémoglobine → <span class=\"kw-bio\">bilirubine</span> → <span class=\"kw-bio\">ferritine</span> → méthémoglobine)</td><td>Surnageant clair, absence de pigments sanguins</td></tr>\n          <tr><td>Cytologie</td><td>GR abondants, <span class=\"kw-bio\">rapport GR/GB &gt; 10³</span> (sensible, peu spécifique) ; leucocytose secondairement lymphocytaire ; <span class=\"kw-bio\">sidérophages</span></td><td>Rapport GR/GB superposable à celui du sang</td></tr>\n          <tr><td>Biochimie</td><td>Glycorachie normale, <span class=\"kw-bio\">hyperprotéinorachie</span></td><td>Normale</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> La <span class=\"kw-bio\">spectrophotométrie</span> du surnageant est plus sensible et spécifique que l'analyse visuelle. Au-delà de <span class=\"kw-chiffre\">14 jours</span>, la sensibilité du <span class=\"kw-bio\">LCS</span> chute : une PL normale ne permet plus d'exclure l'HSA.\n      </div>","frequence":0},{"id":"341-7","rang":"A","rubrique":"Contenu multimédia","titre":"Tomodensitométrie d’une hémorragie méningée sous-arachnoïdienne","contenu":"<p>L'<span class=\"kw-radio\">hyperdensité spontanée</span> des espaces sous-arachnoïdiens est le signe pivot du diagnostic <span class=\"kw-imagerie\">TDM</span>. Voici un exemple typique sur coupe axiale non injectée :</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/341/tdm-hsa-ventriculaire.png\" alt=\"TDM cérébrale axiale non injectée : hémorragie sous-arachnoïdienne avec extension intra-ventriculaire droite\">\n        <figcaption>Hémorragie sous-arachnoïdienne avec extension <span class=\"kw-radio\">intra-ventriculaire droite</span> (hyperdensité spontanée comblant les sillons et le ventricule latéral droit).</figcaption>\n      </figure>\n      <p><strong>Sémiologie à reconnaître :</strong></p>\n      <ul>\n        <li><span class=\"kw-radio\">Hyperdensité spontanée</span> des citernes de la base (citerne interpédonculaire, citerne pré-pontique, citernes ambiantes)</li>\n        <li><span class=\"kw-radio\">Comblement des vallées sylviennes (scissures latérales) et de la scissure interhémisphérique</span></li>\n        <li>Comblement des <span class=\"kw-radio\">sillons corticaux</span> (<span class=\"kw-radio\">effacement du dessin normal des circonvolutions</span>)</li>\n        <li>Aspect en <span class=\"kw-radio\">« moulage » du polygone de Willis</span> si saignement massif</li>\n        <li>Complications associées à rechercher : <span class=\"kw-alerte\">hématome intra-parenchymateux</span>, <span class=\"kw-alerte\">hémorragie intra-ventriculaire</span>, <span class=\"kw-alerte\">hydrocéphalie aiguë</span></li>\n      </ul>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/341/tdm-hsa-hip-associe.png\" alt=\"TDM cérébrale non injectée : hémorragie sous-arachnoïdienne compliquée d'un hématome intra-parenchymateux\">\n        <figcaption>HSA compliquée d'un <span class=\"kw-alerte\">hématome intra-parenchymateux</span> — l'hyperdensité sous-arachnoïdienne s'associe à une <span class=\"kw-radio\">collection hyperdense intra-cérébrale</span> (hémorragie cérébro-méningée).</figcaption>\n      </figure>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> L'hyperdensité spontanée disparaît en <span class=\"kw-chiffre\">5-8 jours</span>. Un <span class=\"kw-imagerie\">TDM</span> réalisé au-delà de <span class=\"kw-chiffre\">J7</span>-J8 peut être faussement normal — penser à la PL si la suspicion persiste.\n      </div>","frequence":1},{"id":"341-8","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître la stratégie d’exploration complémentaire à visée étiologique","contenu":"<p>Dès que l'HSA est confirmée, une <strong>exploration étiologique</strong> est lancée pour identifier l'anévrisme et orienter la prise en charge.</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Modalités et indications</th></tr></thead>\n        <tbody>\n          <tr><td>1ʳᵉ intention</td><td><strong>Examen :</strong> <span class=\"kw-imagerie\">angioTDM cérébrale</span> avec reconstruction 3D, non invasive<br><strong>Délai :</strong> immédiatement après le <span class=\"kw-imagerie\">TDM</span> non injecté ayant montré l'HSA<br><strong>Apport :</strong> reconstruction 3D du <span class=\"kw-def\">polygone de Willis</span> → visualise l'anévrisme (<span class=\"kw-radio\">image d'addition</span>), précise sa morphologie et ses rapports → oriente la PEC</td></tr>\n          <tr><td>Alternative</td><td><strong>Examen :</strong> <span class=\"kw-imagerie\">ARM</span> (<span class=\"kw-imagerie\">angio-IRM</span>)<br><strong>Limite :</strong> résolution anatomique inférieure à celle de l'<span class=\"kw-imagerie\">angioTDM</span></td></tr>\n          <tr><td>2ⁿᵈᵉ intention</td><td><strong>Examen :</strong> <span class=\"kw-imagerie\">artériographie cérébrale conventionnelle</span> = examen de référence, <span class=\"kw-alerte\">invasif</span> (<span class=\"kw-ttt\">cathétérisme artériel fémoral</span>)<br><strong>Indications :</strong> si l'<span class=\"kw-imagerie\">angioTDM</span> ne conclut pas — répéter à <span class=\"kw-chiffre\">J7-J8</span> si normale ; ou à visée <span class=\"kw-ttt\">thérapeutique</span> (occlusion par <span class=\"kw-ttt\">microcoils</span>)</td></tr>\n          <tr><td>Autres (cas par cas)</td><td><strong>Selon le contexte :</strong> <span class=\"kw-bio\">hémocultures</span> si suspicion d'<span class=\"kw-etio\">anévrisme mycotique</span> (complication d'<span class=\"kw-etio\">endocardite infectieuse</span>) ; <span class=\"kw-imagerie\">échographie rénale</span> (<span class=\"kw-etio\">polykystose</span>) ; <span class=\"kw-bio\">biopsie de peau</span> (affections du collagène)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Exception.</strong> <span class=\"kw-ci\">Sauf HSA péri-mésencéphalique idiopathique</span> — pas de répétition systématique de l'<span class=\"kw-imagerie\">artériographie</span> ; le diagnostic est retenu après plusieurs imageries normales.\n      </div>","frequence":1},{"id":"341-9","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître l’urgence d’une hémorragie méningée","contenu":"<div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Urgence</span> vitale absolue.</strong> <span class=\"kw-def\">Mortalité</span> globale <span class=\"kw-alerte\">40-50 %</span>, dont <span class=\"kw-chiffre\">10-20 %</span> de décès <span class=\"kw-alerte\">avant l'arrivée à l'hôpital</span>. Toute suspicion d'HSA impose un <span class=\"kw-clinique\">transfert urgent et médicalisé</span> vers un centre disposant d'une unité de <span class=\"kw-ttt\">neurochirurgie</span>, de <span class=\"kw-ttt\">neuroradiologie interventionnelle</span> et de <span class=\"kw-ttt\">neuroréanimation</span>.\n      </div>\n      <p>L'<span class=\"kw-alerte\">urgence</span> se décline sur <strong>trois plans</strong> :</p>\n      <table >\n        <thead><tr><th>Plan</th><th>Action immédiate</th></tr></thead>\n        <tbody>\n          <tr><td>Diagnostique</td><td><span class=\"kw-imagerie\">TDM cérébral sans injection</span> en 1ʳᵉ intention, sans délai</td></tr>\n          <tr><td>Étiologique</td><td><span class=\"kw-imagerie\">angioTDM</span> immédiat dès l'HSA confirmée</td></tr>\n          <tr><td>Thérapeutique</td><td>Exclusion de l'anévrisme dans les <span class=\"kw-chiffre\">≤ 48 h</span> (<span class=\"kw-ttt\">clippage</span> ou <span class=\"kw-ttt\">embolisation</span>) pour prévenir la <span class=\"kw-alerte\">récidive hémorragique</span>, dont l'<span class=\"kw-def\">incidence</span> est maximale dans les <span class=\"kw-chiffre\">24 premières heures</span></td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"341-10","rang":"A","rubrique":"Prise en charge","titre":"Connaître le traitement symptomatique initial","contenu":"<p>Le traitement symptomatique est <strong>débuté sans attendre</strong>, en parallèle du transfert vers un centre spécialisé.</p>\n      <table >\n        <thead><tr><th>Volet</th><th>Mesures</th></tr></thead>\n        <tbody>\n          <tr><td>Orientation</td><td>Traitement débuté aux urgences ou sur le lieu de PEC ; <span class=\"kw-clinique\">transport médicalisé</span> vers un centre <span class=\"kw-ttt\">USI / neurochirurgie / neuroradiologie interventionnelle / neuroréanimation</span></td></tr>\n          <tr><td>Conditionnement</td><td><strong>Repos :</strong> repos strict au lit, <span class=\"kw-clinique\">position proclive <span class=\"kw-chiffre\">30°</span></span>, isolement neurosensoriel<br><strong>Voie digestive :</strong> à jeun, arrêt des apports oraux ; <span class=\"kw-ttt\">SNG</span> discutée si troubles de vigilance (<span class=\"kw-ci\">contre-indiquée en cas d'HTIC</span>)<br><strong>Hémodynamique :</strong> <span class=\"kw-ttt\">VVP</span>, <span class=\"kw-clinique\">euvolémie</span> (± correction d'une <span class=\"kw-bio\">hyponatrémie</span> par <span class=\"kw-def\">SIADH</span>)<br><strong>Ventilation :</strong> <span class=\"kw-ttt\">intubation</span> si <span class=\"kw-alerte\">coma</span>, <span class=\"kw-alerte\">choc cardiogénique</span> ou <span class=\"kw-alerte\">détresse</span> respiratoire<br><strong>Hémostase :</strong> <span class=\"kw-alerte\">arrêt et antagonisation</span> de tout <span class=\"kw-ttt\">anticoagulant / antiagrégant</span> (y compris <span class=\"kw-ttt\">AINS</span>)</td></tr>\n          <tr><td>Traitements symptomatiques</td><td><strong>Antalgie :</strong> IV sans effet sur l'hémostase — <span class=\"kw-ttt\">paracétamol</span>, <span class=\"kw-ttt\">néfopam</span>, <span class=\"kw-ttt\">morphiniques</span><br><strong>Antiémétiques</strong><br><strong>Anti-épileptique :</strong> <span class=\"kw-alerte\">seulement si crise évidente</span> (pas de prophylaxie)<br><strong>Contrôle de l'<span class=\"kw-etio\">HTA</span> :</strong> <span class=\"kw-ttt\">nicardipine IVSE</span></td></tr>\n          <tr><td>Traitements préventifs</td><td><strong>Vasospasme :</strong> <span class=\"kw-ttt\">nimodipine</span> per os ou IV pendant <span class=\"kw-chiffre\">21 jours</span> (<span class=\"kw-def\">surveillance</span> PA, risque d'<span class=\"kw-clinique\">hypotension</span>)<br><strong>MTEV :</strong> compression pneumatique d'abord, puis <span class=\"kw-ttt\">HBPM</span> après exclusion de l'anévrisme<br><strong>Ulcère de stress :</strong> prévention systématique</td></tr>\n          <tr><td><span class=\"kw-def\">Surveillance</span></td><td>Continue : pouls, PA, conscience toutes les heures ; température toutes les <span class=\"kw-chiffre\">8 h</span><br>Durée <span class=\"kw-chiffre\">≥ 14 jours</span>, à la recherche d'un <span class=\"kw-alerte\">déficit neurologique retardé</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong><span class=\"kw-imagerie\">Doppler transcrânien</span>.</strong> Outil de <span class=\"kw-def\">surveillance</span> au lit du patient : un effondrement des vitesses diastoliques oriente vers une <span class=\"kw-alerte\">HTIC</span> ; une accélération des vélocités moyennes oriente vers un <span class=\"kw-alerte\">vasospasme</span>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 224 — <span class=\"kw-etio\">HTA</span> · 332 — Etat de <span class=\"kw-alerte\">choc</span></em></p>","frequence":0},{"id":"341-11","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes du traitement étiologique","contenu":"<p>L'<strong>exclusion de l'anévrisme</strong> doit être réalisée dans les <span class=\"kw-chiffre\">≤ 48 h</span>. Le choix entre les deux techniques fait l'objet d'une <span class=\"kw-clinique\">concertation en RCP</span> neurochirurgie + neuroradiologie interventionnelle.</p>\n      <table >\n        <thead><tr><th>Technique</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td>Endovasculaire — embolisation (1ʳᵉ intention)</td><td><strong>Principe :</strong> montée d'un <span class=\"kw-ttt\">microcathéter</span> par voie artérielle jusque dans le sac, dépôt in situ de <span class=\"kw-ttt\">coils en spires métalliques</span>, sous <span class=\"kw-ttt\">anesthésie générale</span><br><strong>Avantage :</strong> <span class=\"kw-clinique\">morbidité moindre</span> ; préférée si les 2 techniques sont possibles à risque et probabilité d'occlusion équivalents</td></tr>\n          <tr><td>Chirurgical — clippage</td><td><strong>Principe :</strong> <span class=\"kw-ttt\">craniotomie</span>, <span class=\"kw-etio\">dissection</span> sous microscope opératoire, pose d'un <span class=\"kw-ttt\">clip en titane</span> sur le collet de l'anévrisme<br><strong>Avantage :</strong> permet d'associer d'autres gestes — évacuation d'un <span class=\"kw-alerte\">hématome intra-parenchymateux</span> par effet de <span class=\"kw-clinique\">masse</span>, <span class=\"kw-ttt\">dérivation ventriculaire</span> si hydrocéphalie, <span class=\"kw-ttt\">craniectomie décompressive</span> si <span class=\"kw-alerte\">HTIC</span> pure</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Astuce QCM.</strong> Le choix endovasculaire / chirurgical est une <strong>décision multidisciplinaire</strong> : en QCM, les deux techniques sont à cocher comme possibles.\n      </div>\n      <p><strong>Cas particuliers</strong> :</p>\n      <ul>\n        <li><span class=\"kw-etio\">HSA péri-mésencéphalique idiopathique</span> : pas de traitement étiologique spécifique, <span class=\"kw-def\">surveillance</span>, <span class=\"kw-alerte\">bon pronostic</span></li>\n        <li><span class=\"kw-etio\">Anévrisme mycotique</span> : <span class=\"kw-ttt\">antibiothérapie</span> de l'endocardite infectieuse + discussion de l'exclusion</li>\n      </ul>","frequence":0},{"id":"341-12","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les complications évolutives d’une hémorragie méningée","contenu":"<p>La <span class=\"kw-alerte\">rupture</span> anévrismale déclenche une <span class=\"kw-alerte\">HTIC aiguë</span> et libère du sang dans les espaces sous-arachnoïdiens. Quatre voies physiopathologiques en découlent : ischémie cérébrale globale, vasospasme, obstruction puis fibrose des granulations arachnoïdiennes, activation de la <span class=\"kw-ttt\">fibrinolyse</span>. Les complications se répartissent selon leur délai d'apparition.</p>\n      <figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewBox=\"0 0 770 440\" role=\"img\" aria-label=\"Cascade physiopathologique des complications de la rupture anévrismale\" style=\"height:auto;display:block;border-radius:8px\">\n          <defs><marker id=\"a341casc\" markerWidth=\"9\" markerHeight=\"9\" refX=\"6.5\" refY=\"3\" orient=\"auto\"><path class=\"ah\" d=\"M0,0 L7,3 L0,6 Z\"/></marker></defs>\n          <text x=\"385\" y=\"24\" text-anchor=\"middle\" class=\"tx-title\" font-family=\"Georgia, serif\" font-size=\"14.5\" font-weight=\"700\">Rupture anévrismale — cascade physiopathologique</text>\n          <path d=\"M146,221 C168,221 162,90 182,90\" fill=\"none\" class=\"ln\" stroke-width=\"1.4\" marker-end=\"url(#a341casc)\"/>\n          <path d=\"M146,221 C170,221 164,230 182,230\" fill=\"none\" class=\"ln\" stroke-width=\"1.4\" marker-end=\"url(#a341casc)\"/>\n          <path d=\"M146,221 C168,221 162,380 182,380\" fill=\"none\" class=\"ln\" stroke-width=\"1.4\" marker-end=\"url(#a341casc)\"/>\n          <path d=\"M316,90 C340,90 336,56 360,56\" fill=\"none\" class=\"ln\" stroke-width=\"1.3\" marker-end=\"url(#a341casc)\"/>\n          <path d=\"M316,90 C340,90 336,128 360,128\" fill=\"none\" class=\"ln\" stroke-width=\"1.3\" marker-end=\"url(#a341casc)\"/>\n          <path d=\"M316,230 C340,230 336,208 360,208\" fill=\"none\" class=\"ln\" stroke-width=\"1.3\" marker-end=\"url(#a341casc)\"/>\n          <path d=\"M316,230 C340,230 336,278 360,278\" fill=\"none\" class=\"ln\" stroke-width=\"1.3\" marker-end=\"url(#a341casc)\"/>\n          <path d=\"M316,380 L360,380\" fill=\"none\" class=\"ln\" stroke-width=\"1.3\" marker-end=\"url(#a341casc)\"/>\n          <path d=\"M536,128 L580,128\" fill=\"none\" class=\"ln\" stroke-width=\"1.3\" marker-end=\"url(#a341casc)\"/>\n          <path d=\"M536,208 L580,208\" fill=\"none\" class=\"ln\" stroke-width=\"1.3\" marker-end=\"url(#a341casc)\"/>\n          <path d=\"M536,278 L580,278\" fill=\"none\" class=\"ln\" stroke-width=\"1.3\" marker-end=\"url(#a341casc)\"/>\n          <rect x=\"14\" y=\"198\" width=\"132\" height=\"46\" rx=\"9\" class=\"fb-red\" stroke-width=\"1.6\"/>\n          <text text-anchor=\"middle\" class=\"tx-red\" font-family=\"Georgia, serif\" font-size=\"12.5\" font-weight=\"700\"><tspan x=\"80\" y=\"217\">Rupture</tspan><tspan x=\"80\" y=\"233\">anévrismale</tspan></text>\n          <rect x=\"184\" y=\"70\" width=\"132\" height=\"40\" rx=\"8\" class=\"fb-teal\" stroke-width=\"1.4\"/>\n          <text x=\"250\" y=\"94\" text-anchor=\"middle\" class=\"tx-teal\" font-family=\"Georgia, serif\" font-size=\"11.5\" font-weight=\"600\">↑ PIC aiguë</text>\n          <rect x=\"184\" y=\"210\" width=\"132\" height=\"40\" rx=\"8\" class=\"fb-purple\" stroke-width=\"1.4\"/>\n          <text x=\"250\" y=\"234\" text-anchor=\"middle\" class=\"tx-purple\" font-family=\"Georgia, serif\" font-size=\"11.5\" font-weight=\"600\">Sang dans les ESA</text>\n          <rect x=\"184\" y=\"360\" width=\"132\" height=\"40\" rx=\"8\" class=\"fb-red\" stroke-width=\"1.4\"/>\n          <text x=\"250\" y=\"384\" text-anchor=\"middle\" class=\"tx-red\" font-family=\"Georgia, serif\" font-size=\"11\" font-weight=\"600\">Activation fibrinolyse</text>\n          <rect x=\"360\" y=\"34\" width=\"176\" height=\"44\" rx=\"8\" class=\"fb-teal\" stroke-width=\"1.3\"/>\n          <text text-anchor=\"middle\" class=\"tx-teal\" font-family=\"Georgia, serif\" font-size=\"11\"><tspan x=\"448\" y=\"52\">Ischémie cérébrale</tspan><tspan x=\"448\" y=\"67\">globale aiguë</tspan></text>\n          <rect x=\"360\" y=\"108\" width=\"176\" height=\"40\" rx=\"8\" class=\"fb-teal\" stroke-width=\"1.3\"/>\n          <text x=\"448\" y=\"132\" text-anchor=\"middle\" class=\"tx-teal\" font-family=\"Georgia, serif\" font-size=\"11\">Vasospasme artériel</text>\n          <rect x=\"360\" y=\"186\" width=\"176\" height=\"44\" rx=\"8\" class=\"fb-purple\" stroke-width=\"1.3\"/>\n          <text text-anchor=\"middle\" class=\"tx-purple\" font-family=\"Georgia, serif\" font-size=\"11\"><tspan x=\"448\" y=\"204\">Obstruction des</tspan><tspan x=\"448\" y=\"219\">granulations arachn.</tspan></text>\n          <rect x=\"360\" y=\"256\" width=\"176\" height=\"44\" rx=\"8\" class=\"fb-purple\" stroke-width=\"1.3\"/>\n          <text text-anchor=\"middle\" class=\"tx-purple\" font-family=\"Georgia, serif\" font-size=\"11\"><tspan x=\"448\" y=\"274\">Fibrose des</tspan><tspan x=\"448\" y=\"289\">granulations arachn.</tspan></text>\n          <rect x=\"360\" y=\"360\" width=\"176\" height=\"40\" rx=\"8\" class=\"fb-red\" stroke-width=\"1.3\"/>\n          <text x=\"448\" y=\"384\" text-anchor=\"middle\" class=\"tx-red\" font-family=\"Georgia, serif\" font-size=\"11\" font-weight=\"600\">Récidive du saignement</text>\n          <rect x=\"580\" y=\"106\" width=\"172\" height=\"44\" rx=\"8\" class=\"fb-teal\" stroke-width=\"1.3\"/>\n          <text text-anchor=\"middle\" class=\"tx-teal\" font-family=\"Georgia, serif\" font-size=\"11\"><tspan x=\"666\" y=\"124\">Ischémie cérébrale</tspan><tspan x=\"666\" y=\"139\">retardée (<span class=\"kw-chiffre\">30 %</span>)</tspan></text>\n          <rect x=\"580\" y=\"186\" width=\"172\" height=\"44\" rx=\"8\" class=\"fb-purple\" stroke-width=\"1.3\"/>\n          <text text-anchor=\"middle\" class=\"tx-purple\" font-family=\"Georgia, serif\" font-size=\"11\"><tspan x=\"666\" y=\"204\">Hydrocéphalie</tspan><tspan x=\"666\" y=\"219\">aiguë</tspan></text>\n          <rect x=\"580\" y=\"256\" width=\"172\" height=\"44\" rx=\"8\" class=\"fb-purple\" stroke-width=\"1.3\"/>\n          <text text-anchor=\"middle\" class=\"tx-purple\" font-family=\"Georgia, serif\" font-size=\"11\"><tspan x=\"666\" y=\"274\">Hydrocéphalie</tspan><tspan x=\"666\" y=\"289\">chronique (HPN)</tspan></text>\n          <text x=\"666\" y=\"166\" text-anchor=\"middle\" class=\"tx-green\" font-family=\"Georgia, serif\" font-size=\"10\" font-style=\"italic\">↳ Nimodipine 21 j</text>\n          <text x=\"666\" y=\"245\" text-anchor=\"middle\" class=\"tx-green\" font-family=\"Georgia, serif\" font-size=\"10\" font-style=\"italic\">↳ dérivation ventric. externe</text>\n          <text x=\"666\" y=\"315\" text-anchor=\"middle\" class=\"tx-green\" font-family=\"Georgia, serif\" font-size=\"10\" font-style=\"italic\">↳ dérivation ventric.-périt.</text>\n          <text x=\"448\" y=\"414\" text-anchor=\"middle\" class=\"tx-green\" font-family=\"Georgia, serif\" font-size=\"10\" font-style=\"italic\">↳ exclusion de l'anévrisme <span class=\"kw-chiffre\">≤ 48 h</span></text>\n        </svg>\n        <figcaption>Trois voies à partir de la rupture : <span class=\"kw-clinique\">↑ PIC</span> (ischémie globale + <span class=\"kw-alerte\">vasospasme</span> → ischémie retardée), <span class=\"kw-bio\">sang dans les ESA</span> (obstruction/fibrose des granulations → hydrocéphalie aiguë puis chronique) et <span class=\"kw-alerte\">fibrinolyse</span> (récidive). En vert : la parade thérapeutique de chaque branche.</figcaption>\n      </figure>\n      <table >\n        <thead><tr><th>Délai</th><th>Principales</th><th>Autres</th></tr></thead>\n        <tbody>\n          <tr><td>Complications précoces</td><td>\n            <strong><span class=\"kw-alerte\">Récidive du saignement</span> :</strong> <span class=\"kw-def\">incidence</span> maximale <span class=\"kw-chiffre\">&lt; 24 h</span> ; la <span class=\"kw-ttt\">fibrinolyse</span> physiologique détruit le clou plaquettaire ; <span class=\"kw-def\">mortalité</span> <span class=\"kw-chiffre\">30-70 %</span><br>\n            <strong><span class=\"kw-alerte\">Hydrocéphalie aiguë</span> :</strong> précoce (<span class=\"kw-chiffre\">3-72 h</span>) ou retardée (<span class=\"kw-chiffre\">3ᵉ jour à 3ᵉ semaine</span>), obstructive ; CAT = <span class=\"kw-ttt\">dérivation ventriculaire externe</span> avant embolisation<br>\n            <strong><span class=\"kw-alerte\">HTIC aiguë</span></strong><br>\n            <strong><span class=\"kw-clinique\">Hyponatrémie</span> :</strong> <span class=\"kw-etio\">syndrome de perte de sel</span> (DEC, sécrétion inappropriée de <span class=\"kw-bio\">BNP</span> — <span class=\"kw-ttt\">NaCl ± hydrocortisone + fludrocortisone</span>) ou <span class=\"kw-def\">SIADH</span> (euvolémie — restriction hydrique)\n          </td><td>\n            <strong><span class=\"kw-clinique\">Cardiaques</span> :</strong> <span class=\"kw-clinique\">tako-tsubo</span>, troubles du rythme et de conduction, <span class=\"kw-ci\">insuffisance cardiaque</span>, <span class=\"kw-alerte\">OAP</span> (orage catécholaminergique)<br>\n            <strong>Crises d'épilepsie :</strong> si HSA abondante, hématome intra-parenchymateux, ischémie<br>\n            <strong><span class=\"kw-clinique\">Hyperthermie</span></strong><br>\n            <strong>Complications de <span class=\"kw-alerte\">réanimation</span> :</strong> pneumopathie, ulcère de stress\n          </td></tr>\n          <tr><td>Complications tardives</td><td>\n            <strong><span class=\"kw-alerte\">Ischémie cérébrale retardée (30 %)</span> :</strong> entre J4 et J14 (pic <span class=\"kw-chiffre\">J7-J8</span>) ; complique un vasospasme distal ± proximal ; à distinguer du vasospasme (image radiologique) et du déficit neurologique retardé (clinique) ; diagnostic = doppler transcrânien (↑ vitesses moyennes), <span class=\"kw-imagerie\">angioTDM</span> / <span class=\"kw-imagerie\">artériographie</span>, <span class=\"kw-imagerie\">TDM de perfusion</span> ; <span class=\"kw-imagerie\">IRM</span> avec séquences <span class=\"kw-alerte\">AVC</span> pour l'ischémie constituée ; prévention = <span class=\"kw-ttt\">nimodipine</span> + euvolémie + normotension + lutte contre l'hyponatrémie<br>\n            <strong><span class=\"kw-alerte\">Hydrocéphalie chronique à pression normale</span> :</strong> fibrose des granulations arachnoïdiennes ; <span class=\"kw-clinique\">triade de Hakim et Adams</span> ; CAT = <span class=\"kw-ttt\">dérivation ventriculo-péritonéale</span>\n          </td><td>\n            <strong><span class=\"kw-clinique\">Épilepsie</span></strong><br>\n            <strong>Troubles cognitifs et comportementaux :</strong> frein principal au retour socioprofessionnel<br>\n            <strong><span class=\"kw-clinique\">Anosmie</span> :</strong> anévrisme de la communicante antérieure\n          </td></tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewBox=\"0 0 780 286\" role=\"img\" aria-label=\"Frise chronologique des complications de l'hémorragie sous-arachnoïdienne\" style=\"height:auto;display:block;border-radius:8px\">\n          <defs><marker id=\"a341fr\" markerWidth=\"9\" markerHeight=\"9\" refX=\"6.5\" refY=\"3\" orient=\"auto\"><path class=\"ah\" d=\"M0,0 L7,3 L0,6 Z\"/></marker></defs>\n          <text x=\"390\" y=\"24\" text-anchor=\"middle\" class=\"tx-title\" font-family=\"Georgia, serif\" font-size=\"14.5\" font-weight=\"700\">Quand surveiller quoi — frise des complications</text>\n          <rect x=\"70\" y=\"142\" width=\"515\" height=\"16\" rx=\"4\" class=\"band\" fill-opacity=\"0.2\"/>\n          <line x1=\"55\" y1=\"150\" x2=\"745\" y2=\"150\" class=\"ln\" stroke-width=\"2\" marker-end=\"url(#a341fr)\"/>\n          <g class=\"ln\" stroke-width=\"1.4\"><line x1=\"70\" y1=\"145\" x2=\"70\" y2=\"155\"/><line x1=\"205\" y1=\"145\" x2=\"205\" y2=\"155\"/><line x1=\"325\" y1=\"145\" x2=\"325\" y2=\"155\"/><line x1=\"480\" y1=\"145\" x2=\"480\" y2=\"155\"/><line x1=\"585\" y1=\"145\" x2=\"585\" y2=\"155\"/><line x1=\"690\" y1=\"145\" x2=\"690\" y2=\"155\"/></g>\n          <text x=\"70\" y=\"174\" text-anchor=\"middle\" class=\"tx-muted\" font-family=\"Georgia, serif\" font-size=\"9.5\"><span class=\"kw-chiffre\">H0</span> · <span class=\"kw-alerte\">rupture</span></text>\n          <text x=\"205\" y=\"174\" text-anchor=\"middle\" class=\"tx-muted\" font-family=\"Georgia, serif\" font-size=\"9.5\">&lt;<span class=\"kw-chiffre\"> 24 h</span></text>\n          <text x=\"325\" y=\"174\" text-anchor=\"middle\" class=\"tx-muted\" font-family=\"Georgia, serif\" font-size=\"9.5\"><span class=\"kw-chiffre\">3–72 h</span></text>\n          <text x=\"480\" y=\"174\" text-anchor=\"middle\" class=\"tx-muted\" font-family=\"Georgia, serif\" font-size=\"9.5\">J4–J14 · pic <span class=\"kw-chiffre\">J7</span>-8</text>\n          <text x=\"585\" y=\"174\" text-anchor=\"middle\" class=\"tx-muted\" font-family=\"Georgia, serif\" font-size=\"9.5\">J14</text>\n          <text x=\"690\" y=\"174\" text-anchor=\"middle\" class=\"tx-muted\" font-family=\"Georgia, serif\" font-size=\"9.5\">sem.–mois</text>\n          <circle cx=\"70\" cy=\"150\" r=\"5\" class=\"dot-red\"/>\n          <line x1=\"205\" y1=\"150\" x2=\"205\" y2=\"92\" class=\"ln-red\" stroke-width=\"1.2\" stroke-dasharray=\"3 3\"/>\n          <rect x=\"128\" y=\"48\" width=\"154\" height=\"44\" rx=\"8\" class=\"fb-red\" stroke-width=\"1.4\"/>\n          <text text-anchor=\"middle\" class=\"tx-red\" font-family=\"Georgia, serif\" font-size=\"10.5\" font-weight=\"700\"><tspan x=\"205\" y=\"68\">Récidive du saignement</tspan><tspan x=\"205\" y=\"83\">(PIC max · <span class=\"kw-def\">mortalité</span><span class=\"kw-chiffre\"> 30-70 %</span>)</tspan></text>\n          <line x1=\"480\" y1=\"150\" x2=\"480\" y2=\"92\" class=\"ln-red\" stroke-width=\"1.2\" stroke-dasharray=\"3 3\"/>\n          <rect x=\"394\" y=\"44\" width=\"172\" height=\"48\" rx=\"8\" class=\"fb-red\" stroke-width=\"1.4\"/>\n          <text text-anchor=\"middle\" class=\"tx-red\" font-family=\"Georgia, serif\" font-size=\"10.5\" font-weight=\"700\"><tspan x=\"480\" y=\"64\">Vasospasme →</tspan><tspan x=\"480\" y=\"79\">Ischémie retardée (<span class=\"kw-chiffre\">30 %</span>)</tspan></text>\n          <line x1=\"325\" y1=\"150\" x2=\"325\" y2=\"196\" class=\"ln-purple\" stroke-width=\"1.2\" stroke-dasharray=\"3 3\"/>\n          <rect x=\"245\" y=\"196\" width=\"160\" height=\"42\" rx=\"8\" class=\"fb-purple\" stroke-width=\"1.4\"/>\n          <text text-anchor=\"middle\" class=\"tx-purple\" font-family=\"Georgia, serif\" font-size=\"10.5\"><tspan x=\"325\" y=\"214\">Hydrocéphalie aiguë</tspan><tspan x=\"325\" y=\"229\">(obstructive · DVE)</tspan></text>\n          <line x1=\"690\" y1=\"150\" x2=\"690\" y2=\"190\" class=\"ln-purple\" stroke-width=\"1.2\" stroke-dasharray=\"3 3\"/>\n          <rect x=\"600\" y=\"190\" width=\"160\" height=\"56\" rx=\"8\" class=\"fb-purple\" stroke-width=\"1.4\"/>\n          <text text-anchor=\"middle\" class=\"tx-purple\" font-family=\"Georgia, serif\" font-size=\"10.5\"><tspan x=\"680\" y=\"208\">Hydrocéphalie chronique</tspan><tspan x=\"680\" y=\"223\">(HPN · DVP)</tspan><tspan x=\"680\" y=\"238\">tbles cognitifs · épilepsie</tspan></text>\n          <text x=\"327\" y=\"276\" text-anchor=\"middle\" class=\"tx-green\" font-family=\"Georgia, serif\" font-size=\"9.5\" font-style=\"italic\"><span class=\"kw-def\">surveillance</span> continue <span class=\"kw-chiffre\">≥ 14</span> j — recherche d'un déficit neurologique retardé</text>\n        </svg>\n        <figcaption>Axe temporel des complications : <span class=\"kw-alerte\">récidive</span> (pic &lt; <span class=\"kw-chiffre\">24 h</span>) et <span class=\"kw-alerte\">vasospasme / ischémie retardée</span> (J4-J14) au-dessus de l'axe ; <span class=\"kw-clinique\">hydrocéphalie</span> aiguë puis chronique en dessous. La bande verte = fenêtre de surveillance rapprochée d'au moins <span class=\"kw-chiffre\">14 jours</span>.</figcaption>\n      </figure>\n      <div class=\"callout callout-danger\">\n        <strong>Récidive <span class=\"kw-etio\">hémorragique</span> = 1ʳᵉ complication à redouter.</strong> <span class=\"kw-def\">Incidence</span> maximale dans les <span class=\"kw-chiffre\">24 premières heures</span>. C'est elle qui justifie l'exclusion en <span class=\"kw-alerte\">urgence</span> (<span class=\"kw-chiffre\">≤ 48 h</span>) de l'anévrisme — il n'y a pas de « calmer le jeu en attendant ».\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 105 — Epilepsie · 267 — Trouble de l'équilibre acido-basique - Désordre hydro-électrolytique · 340 — <span class=\"kw-alerte\">AVC</span> · 234 — <span class=\"kw-ci\">Insuffisance cardiaque</span> · 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë · 236 — Trouble de conduction intracardiaque</em></p>","frequence":5,"liens":[{"href":"https://radiopaedia.org/articles/cerebral-vasospasm-following-subarachnoid-haemorrhage","label":"Radiopaedia : Cerebral vasospasm following subarachnoid haemorrhage"}]}],"astuces":[{"type":"danger","titre":"Céphalée en coup de tonnerre = HSA jusqu'à preuve du contraire","contenu":"Toute céphalée brutale, explosive, maximale d'emblée (« la pire de ma vie ») impose un TDM cérébral en urgence, MÊME si l'examen neurologique est normal. Une céphalée sentinelle non explorée = catastrophe annoncée (resaignement majeur dans les jours qui suivent)."},{"type":"warn","titre":"TDM normal n'exclut pas l'HSA après 6h","contenu":"La sensibilité du TDM est > 95 % dans les 6 premières heures mais chute à 50 % après J7. Si suspicion clinique forte avec TDM normal → PL après 12h (recherche xanthochromie). Ne JAMAIS dire « le scanner est normal, il n'y a pas d'HSA » sans avoir fait la PL."},{"type":"tip","titre":"LCR rouge : 3 tubes pour différencier HSA vs piqûre traumatique","contenu":"HSA = LCR uniformément rouge sur les 3 tubes + xanthochromie après centrifugation. Piqûre traumatique = LCR éclaircit du tube 1 au tube 3, pas de xanthochromie, le LCR coagule. La xanthochromie n'apparaît qu'après 12h → faire la PL au bon moment."},{"type":"danger","titre":"Anévrysme de la communicante postérieure → mydriase + ptosis","contenu":"Une céphalée brutale + paralysie du III homolatérale (mydriase aréactive, ptosis, divergence) = anévrysme de la communicante postérieure en cours de rupture. Urgence absolue. Angio-TDM immédiat puis embolisation/clipping."},{"type":"info","titre":"Polykystose rénale → dépister les anévrysmes","contenu":"PKRAD = risque d'anévrysme intracrânien × 5. Dépistage par angio-IRM systématique à 30 ans, puis tous les 5 ans, surtout si antécédent familial d'HSA. Idem pour ≥ 2 apparentés du 1er degré atteints."},{"type":"warn","titre":"Nimodipine PO 21 jours, pas IV","contenu":"La nimodipine PO 60 mg toutes les 4h pendant 21 jours est le SEUL traitement validé pour réduire les conséquences neurologiques du vasospasme (essais BRANT). La voie IV n'a pas démontré son efficacité supplémentaire et expose à des hypotensions."}],"strategie":{"urgence":"<p><strong>Reconnaître l'HSA <span class=\"q\">— jusqu'à preuve du contraire</span></strong></p><p><span class=\"kw-imagerie\">TDM cérébrale sans injection</span> en <span class=\"kw-alerte\">urgence</span></p><ul><li>Toute <span class=\"kw-clinique\">céphalée brutale</span> (<span class=\"kw-chiffre\">&lt; 1h</span>) voire « en <span class=\"kw-clinique\">coup de tonnerre</span> » (<span class=\"kw-chiffre\">&lt; 1 min</span>), inhabituelle, intense</li><li>Tout <span class=\"kw-clinique\">syndrome méningé</span> non fébrile</li></ul><p><strong>Exclure l'anévrisme rompu <span class=\"q\">— prévention de la récidive</span></strong></p><p>transfert médicalisé vers un centre de <span class=\"kw-ttt\">neuroradiologie interventionnelle</span> / <span class=\"kw-ttt\">neurochirurgie</span></p><ul><li><span class=\"kw-etio\">Rupture d'anévrisme</span> considérée jusqu'à preuve du contraire (<span class=\"kw-chiffre\">85%</span> des HSA)</li><li>Délai de PEC : exclusion de l'anévrisme <span class=\"kw-chiffre\">≤ 48h</span></li></ul><p><strong>Récidive <span class=\"kw-etio\">hémorragique</span> <span class=\"q\">— 1ère complication à redouter</span></strong></p><p>exclure l'anévrisme <span class=\"kw-alerte\">en urgence</span></p><ul><li><span class=\"kw-def\">Incidence</span> maximale <span class=\"kw-chiffre\">&lt; 24h</span> (<span class=\"kw-chiffre\">30%</span> des ruptures), par <span class=\"kw-ttt\">fibrinolyse</span> du clou plaquettaire</li><li><span class=\"kw-alerte\">Mortalité 30-70%</span> en cas de resaignement</li></ul>","hospit":"<p><strong>Pas d'ambulatoire :</strong> <span class=\"kw-alerte\">urgence vitale</span> (<span class=\"kw-def\">mortalité</span> <span class=\"kw-chiffre\">40-50%</span>, dont <span class=\"kw-chiffre\">10-20%</span> avant l'hôpital).<br><strong>Orientation :</strong> transport urgent médicalisé vers un centre associant <span class=\"kw-ttt\">neurochirurgie</span>, <span class=\"kw-ttt\">neuroradiologie interventionnelle</span> et <span class=\"kw-ttt\">neuroréanimation</span>.<br><strong>Hospit :</strong> <span class=\"kw-def\">unité de soins intensifs</span> ou <span class=\"kw-def\">réanimation</span>.<br><strong><span class=\"kw-ttt\">Intubation</span> / ventilation :</strong> si <span class=\"kw-alerte\">coma</span>, <span class=\"kw-alerte\">trouble de la vigilance</span>, <span class=\"kw-alerte\">choc cardiogénique</span> ou <span class=\"kw-alerte\">détresse respiratoire</span>.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Coma d'emblée</span> ou <span class=\"kw-alerte\">trouble de la conscience</span> → <span class=\"kw-def\">HTIC aiguë</span> ou <span class=\"kw-def\">hydrocéphalie aiguë</span></li><li><span class=\"kw-alerte\">Mydriase aréactive</span> / paralysie du <span class=\"kw-clinique\">III</span> (anévrisme de la <span class=\"kw-etio\">carotide interne supraclinoïdienne</span>)</li><li>Nouvelle <span class=\"kw-alerte\">céphalée brutale</span> + aggravation de la conscience → <span class=\"kw-etio\">récidive hémorragique</span></li><li><span class=\"kw-alerte\">Déficit neurologique focal</span> (hématome cérébro-méningé, ou <span class=\"kw-etio\">vasospasme</span> après <span class=\"kw-chiffre\">J4</span>)</li><li><span class=\"kw-alerte\">Instabilité tensionnelle</span> / <span class=\"kw-alerte\">choc</span> avec <span class=\"kw-alerte\">OAP</span> (orage catécholaminergique, <span class=\"kw-etio\">tako-tsubo</span>)</li><li><span class=\"kw-alerte\">Mort subite</span> / troubles de conduction (réflexe de Cushing : <span class=\"kw-clinique\">bradycardie</span> extrême, bloc)</li><li><span class=\"kw-def\">Score</span> <span class=\"kw-def\">WFNS</span> élevé (Glasgow <span class=\"kw-chiffre\">&lt; 8</span> = WFNS V) · score de <span class=\"kw-def\">Fisher</span> élevé au <span class=\"kw-imagerie\">scanner</span></li></ul>","principes":"<p><span class=\"kw-alerte\">Anévrisme rompu jusqu'à preuve du contraire</span> → exclure l'anévrisme <span class=\"kw-chiffre\">≤ 48h</span> pour prévenir la récidive, + neuroprotection et prévention du <span class=\"kw-etio\">vasospasme</span>.</p><p><strong>Conditionnement & symptomatique</strong></p><ul><li><span class=\"kw-ttt\">Repos strict au lit</span>, position proclive <span class=\"kw-chiffre\">30°</span>, isolement neurosensoriel, à jeun</li><li><span class=\"kw-ttt\">VVP</span> : maintien de l'euvolémie (± correction d'une <span class=\"kw-bio\">hyponatrémie</span>)</li><li>Antalgie IV sans effet sur l'hémostase : <span class=\"kw-ttt\">paracétamol</span>, <span class=\"kw-ttt\">néfopam</span>, <span class=\"kw-ttt\">morphinique</span> ; antiémétiques</li><li>Contrôle de l'<span class=\"kw-etio\">HTA</span> : <span class=\"kw-ttt\">nicardipine IVSE</span> si besoin</li><li><span class=\"kw-ci\">Arrêt / antagonisation de tout anticoagulant ou antiagrégant</span> (y compris <span class=\"kw-ci\">AINS</span>)</li><li><span class=\"kw-ttt\">Anti-épileptique</span> seulement en cas de crise (pas de prophylaxie)</li></ul><p><strong>Prévention du vasospasme</strong></p><ul><li><span class=\"kw-ttt\">Nimodipine</span> pendant <span class=\"kw-chiffre\">21 jours</span> (per os ou IVSE, <span class=\"kw-def\">surveillance</span> de la PA)</li><li>Maintien euvolémie, normotension, normoxie ; lutte contre l'<span class=\"kw-bio\">hyponatrémie</span></li></ul><p><strong>Traitement étiologique — exclusion de l'anévrisme (<span class=\"kw-chiffre\">≤ 48h</span>)</strong></p><ul><li><span class=\"kw-ttt\">Endovasculaire</span> (coils) en <span class=\"kw-chiffre\">1ère intention</span> : <span class=\"kw-def\">morbidité</span> moindre</li><li><span class=\"kw-ttt\">Chirurgie</span> (clip en titane) si geste associé nécessaire (évacuation d'hématome, <span class=\"kw-ttt\">DVE</span>)</li><li>Choix en <span class=\"kw-ttt\">concertation multidisciplinaire</span> ; si techniques équivalentes → endovasculaire</li></ul><p><strong>Prévention des autres complications</strong></p><ul><li>MTEV : <span class=\"kw-ttt\">compression pneumatique</span> puis <span class=\"kw-ttt\">HBPM</span> après exclusion de l'anévrisme</li><li>Prévention de l'<span class=\"kw-ttt\">ulcère de stress</span></li><li><span class=\"kw-ttt\">DVE</span> du <span class=\"kw-bio\">LCS</span> si <span class=\"kw-etio\">hydrocéphalie aiguë</span></li></ul>","suivi":"<p><strong><span class=\"kw-def\">Surveillance</span> neurologique rapprochée</strong></p><ul><li>Conscience, pouls, PA toutes les heures ; température toutes les <span class=\"kw-chiffre\">8h</span></li><li>Pendant <span class=\"kw-chiffre\">≥ 14 jours</span>, à la recherche d'un <span class=\"kw-alerte\">déficit neurologique retardé</span></li></ul><p><strong>Doppler transcrânien</strong></p><ul><li>À partir de <span class=\"kw-chiffre\">J5</span>, réalisable au lit du patient</li><li>Accélération des <span class=\"kw-clinique\">vélocités moyennes</span> → <span class=\"kw-etio\">vasospasme</span> ; effondrement des vitesses diastoliques → <span class=\"kw-def\">HTIC</span></li></ul><p><strong>Complications à dépister</strong></p><ul><li><span class=\"kw-etio\">Ischémie cérébrale retardée</span> : <span class=\"kw-chiffre\">J4-J14</span> (pic <span class=\"kw-chiffre\">J7-J8</span>)</li><li><span class=\"kw-etio\">Hydrocéphalie chronique</span> → dérivation ventriculo-péritonéale</li><li><span class=\"kw-etio\">Épilepsie</span>, troubles cognitifs, <span class=\"kw-etio\">anosmie</span> (anévrisme de la communicante antérieure)</li></ul>"},"liensGlobaux":[{"href":"https://www.cen-neurologie.fr/second-cycle/hemorragie-meningee-non-traumatique","label":"Collège (CEN) — Hemorragie meningee non traumatique"},{"href":"https://campus.neurochirurgie.fr/article1789.html","label":"Collège — Article1789"},{"href":"https://www.ce-mir.fr/sites/www.ce-mir.fr/files/medias/documents/32.%20H%C3%A9morragie%20sous-arachno%C3%AFdienne.pdf","label":"CeMIR — 32. hémorragie sous arachnoïdienne"},{"href":"https://radiopaedia.org/articles/subarachnoid-haemorrhage","label":"Radiopaedia : Subarachnoid haemorrhage"},{"href":"https://info-radiologie.ch/citerne-sous-arachnoidien.php","label":"Citerne sous arachnoidien"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Céphalée brutale en coup de tonnerre / syndrome méningé non fébrile — HSA jusqu'à preuve du contraire → TDM cérébrale sans injection en urgence","detail":"<h4>CAT — hémorragie méningée non traumatique — Démarche diagnostique → traitement étiologique</h4>","branches":[{"to":"q-angio","label":"TDM : hyperdensité spontanée des espaces sous-arachnoïdiens","color":"amber"},{"to":"q-pl","label":"TDM normale (n'élimine pas l'HSA)","color":"blue"}]},{"id":"q-angio","kind":"decision","label":"AngioTDM cérébrale : anévrisme identifié ? — Reconstruction 3D du polygone de Willis, immédiatement après la TDM","branches":[{"to":"t-anevrismale","label":"Anévrisme identifié (image d'addition)","color":"red"},{"to":"t-perimeso","label":"Pas d'anévrisme, siège péri-mésencéphalique","color":"green"}]},{"id":"t-anevrismale","kind":"terminal","label":"HSA anévrismale — exclusion de l'anévrisme ≤ 48h","color":"red","detail":"<h4>Confirmation</h4><ul><li><span class=\"kw-imagerie\">AngioTDM</span> avec reconstruction 3D du polygone de Willis (<span class=\"kw-chiffre\">1ère intention</span>)</li><li><span class=\"kw-imagerie\">Artériographie</span> conventionnelle = référence si doute (répéter à <span class=\"kw-chiffre\">J7-J8</span> si négative)</li></ul><h4>Traitement endovasculaire (<span class=\"kw-chiffre\">1ère intention</span>)</h4><ul><li><span class=\"kw-ttt\">Coils</span> (spires métalliques) déposés in situ par microcathéter, sous <span class=\"kw-ttt\">anesthésie générale</span></li><li><span class=\"kw-def\">Morbidité</span> moindre que la <span class=\"kw-ttt\">chirurgie</span></li></ul><h4>Traitement chirurgical</h4><ul><li><span class=\"kw-ttt\">Clip en titane</span> par craniotomie</li><li>Préféré si geste associé : évacuation d'hématome, <span class=\"kw-ttt\">DVE</span> d'une hydrocéphalie</li></ul><h4>Décision</h4><ul><li><span class=\"kw-ttt\">Concertation multidisciplinaire</span> ; si techniques équivalentes → endovasculaire ; délai <span class=\"kw-chiffre\">≤ 48h</span></li></ul><h4>Mesures associées</h4><ul><li><span class=\"kw-ttt\">Nimodipine</span> <span class=\"kw-chiffre\">21 jours</span> (prévention du <span class=\"kw-etio\">vasospasme</span>)</li><li>Repos strict proclive <span class=\"kw-chiffre\">30°</span>, contrôle <span class=\"kw-etio\">HTA</span> (<span class=\"kw-ttt\">nicardipine IVSE</span>)</li><li>Prévention <span class=\"kw-ttt\">MTEV</span> / <span class=\"kw-ttt\">ulcère de stress</span></li></ul>"},{"id":"t-perimeso","kind":"terminal","label":"HSA péri-mésencéphalique idiopathique","color":"green","detail":"<h4>Définition</h4><ul><li>Saignement peu abondant de la <span class=\"kw-imagerie\">citerne interpédonculaire</span> (<span class=\"kw-chiffre\">10%</span>), diagnostic d'exclusion</li></ul><h4>Bilan</h4><ul><li><span class=\"kw-imagerie\">Angiographie</span> indispensable (<span class=\"kw-imagerie\">angioTDM</span> ou <span class=\"kw-imagerie\">artériographie</span>) ; si normale → diagnostic retenu</li></ul><h4><span class=\"kw-def\">Pronostic</span></h4><ul><li><span class=\"kw-def\">Bon pronostic</span>, récidive exceptionnelle</li></ul>"},{"id":"q-pl","kind":"decision","label":"Ponction lombaire (> 6h) : surnageant xanthochromique ? — PL jamais d'emblée ; contre-indiquée si HIP / hydrocéphalie avec effet de masse au scanner","branches":[{"to":"t-pl-pos","label":"PL positive (surnageant xanthochromique)","color":"amber"},{"to":"t-ecarte","label":"PL normale (> 12h)","color":"green"}]},{"id":"t-pl-pos","kind":"terminal","label":"HSA confirmée par la PL","color":"amber","detail":"<h4><span class=\"kw-bio\">LCS</span></h4><ul><li>Surnageant <span class=\"kw-bio\">xanthochromique</span> après centrifugation (<span class=\"kw-chiffre\">100%</span> entre <span class=\"kw-chiffre\">12h</span> et 14j)</li><li>Liquide <span class=\"kw-bio\">incoagulable</span>, rapport <span class=\"kw-bio\">GR/GB &gt; 10³</span>, hyperprotéinorachie</li></ul><h4>Délais</h4><ul><li>PL réalisée <span class=\"kw-chiffre\">&gt; 6h</span> (avant : ne l'élimine pas) ; normalité <span class=\"kw-chiffre\">&gt; 12h</span> élimine fortement l'HSA</li></ul><h4>Suite</h4><ul><li>Poursuivre par une <span class=\"kw-imagerie\">angioTDM cérébrale</span> à visée étiologique (anévrisme ? péri-mésencéphalique ?)</li></ul>"},{"id":"t-ecarte","kind":"terminal","label":"Diagnostic d'HSA écarté","color":"green","detail":"<h4><span class=\"kw-bio\">LCS</span></h4><ul><li>Surnageant clair, absence de pigments sanguins, rapport <span class=\"kw-bio\">GR/GB</span> superposable au sang (PL traumatique)</li></ul><h4>Délais</h4><ul><li>Normalité d'une PL <span class=\"kw-chiffre\">&gt; 12h</span> élimine fortement l'HSA (sensibilité diminue au-delà de <span class=\"kw-chiffre\">2 semaines</span>)</li></ul><h4>Conduite</h4><ul><li>Rechercher une autre cause à la <span class=\"kw-clinique\">céphalée</span></li></ul>"}]},"cards":[{"i":"18218d1998ca","n":341,"o":"341-10","u":"Prise en charge","t":"Connaître le traitement symptomatique initial","q":"Quelles sont les préventions médicamenteuses et physiques à initier dès la prise en charge d'une hémorragie méningée non traumatique (HMNT) ?","a":"<p>Dès la prise en charge d'une HMNT, il faut initier :</p><ul><li>La prévention du <strong>vasospasme</strong> par <strong>nimodipine per os ou IV</strong> durant <strong>21 jours</strong>, en surveillant la tension artérielle en raison du risque d'hypotension.</li><li>La prévention de la <strong>maladie thromboembolique veineuse (MTEV)</strong> par compression pneumatique d'abord, puis par Héparine de Bas Poids Moléculaire (HBPM) après exclusion de l'anévrisme.</li><li>La prévention systématique de l'<strong>ulcère de stress</strong>.</li></ul>"},{"i":"2268009c0c32","n":341,"o":"341-10","u":"Prise en charge","t":"Connaître le traitement symptomatique initial","q":"Comment doit être gérée l'hémodynamique, la ventilation et l'hémostase en phase initiale d'une hémorragie méningée non traumatique (HMNT) ?","a":"<p>Pour l'HMNT, il est essentiel de :</p><ul><li>Assurer une <strong>euvolémie</strong> par voie veineuse périphérique (VVP), et corriger une éventuelle hyponatrémie (syndrome de sécrétion inappropriée d'hormone antidiurétique - SIADH).</li><li>Procéder à une <strong>intubation</strong> en cas de coma, de choc cardiogénique ou de détresse respiratoire.</li><li><strong>Arrêter et antagoniser</strong> tout anticoagulant ou antiagrégant plaquettaire, y compris les AINS.</li></ul>"},{"i":"a35f5a4f7a2b","n":341,"o":"341-10","u":"Prise en charge","t":"Connaître le traitement symptomatique initial","q":"Quels sont les traitements symptomatiques spécifiques à administrer en urgence lors d'une hémorragie méningée non traumatique (HMNT) ?","a":"<p>Les traitements symptomatiques de l'HMNT comprennent :</p><ul><li>L'<strong>antalgie IV</strong>, sans effet sur l'hémostase (<strong>paracétamol</strong>, <strong>néfopam</strong>, morphiniques).</li><li>Des <strong>antiémétiques</strong>.</li><li>Un <strong>anti-épileptique</strong> en cas de crise avérée (pas de prophylaxie).</li><li>Le contrôle de l'<strong>HTA</strong> par <strong>nicardipine IVSE</strong>.</li></ul>"},{"i":"b129b9c4a6ce","n":341,"o":"341-10","u":"Prise en charge","t":"Connaître le traitement symptomatique initial","q":"Quelle surveillance est impérative et quels signes faut-il rechercher en continu lors du traitement initial d'une hémorragie méningée non traumatique (HMNT) ?","a":"<p>Une surveillance continue est essentielle pour l'HMNT :</p><ul><li><strong>Pouls</strong>, <strong>Pression Artérielle (PA)</strong>, <strong>conscience</strong> toutes les heures.</li><li><strong>Température</strong> toutes les 8 heures.</li><li>Cette surveillance doit durer au moins <strong>14 jours</strong>, à la recherche d'un déficit neurologique retardé.</li><li>Le <strong>Doppler transcrânien</strong> est un outil utile au lit du patient pour détecter :<ul><li>Un <strong>effondrement des vitesses diastoliques</strong> qui oriente vers une HTIC.</li><li>Une <strong>accélération des vélocités moyennes</strong> qui oriente vers un vasospasme.</li></ul></li></ul>"},{"i":"d402ead6a4b6","n":341,"o":"341-10","u":"Prise en charge","t":"Connaître le traitement symptomatique initial","q":"Quelle est l'attitude initiale et les premières mesures de conditionnement à adopter pour la prise en charge d'une hémorragie méningée non traumatique (HMNT) en urgence ?","a":"<p>La prise en charge initiale de l'HMNT doit être débutée sans attendre, en parallèle d'un transfert médicalisé vers un centre spécialisé (USI, neurochirurgie, neuroradiologie interventionnelle, neuroréanimation). Le <strong>conditionnement</strong> prioritaire comprend :</p><ul><li>Un <strong>repos strict au lit</strong>.</li><li>Une position <strong>proclive à 30°</strong>.</li><li>Un <strong>isolement neurosensoriel</strong>.</li><li>Mise à <strong>jeun</strong> du patient, avec arrêt des apports oraux. Une SNG peut être discutée si troubles de la vigilance, mais est contre-indiquée en cas d'hypertension intracrânienne (HTIC).</li></ul>"},{"i":"11655d6a282d","n":341,"o":"341-4","u":"Diagnostic positif","t":"Connaître la stratégie d’exploration complémentaire devant un tableau clinique évocateur d’hémorragie méningée","q":"Quelle exploration complémentaire doit être réalisée immédiatement après la confirmation d'une hémorragie méningée, et dans quel but ?","a":"<p>Dès l'hémorragie méningée confirmée (par TDM ou PL positive), une <strong>angio-TDM cérébrale immédiate</strong> doit être réalisée. Son but est l'<strong>exploration étiologique</strong> pour identifier la source du saignement (par exemple, un anévrisme).</p>"},{"i":"6b2d772bcd6c","n":341,"o":"341-4","u":"Diagnostic positif","t":"Connaître la stratégie d’exploration complémentaire devant un tableau clinique évocateur d’hémorragie méningée","q":"Dans quel contexte l'IRM cérébrale peut-elle être utilisée dans l'exploration d'une hémorragie méningée non traumatique ?","a":"<p>L'IRM cérébrale est une alternative de <strong>deuxième intention</strong>. Elle est envisagée si la <strong>TDM est négative</strong> et que la <strong>ponction lombaire est impossible</strong>. Sa sensibilité est de 100 % durant les 5 premiers jours.</p>"},{"i":"8ac9b78ee830","n":341,"o":"341-4","u":"Diagnostic positif","t":"Connaître la stratégie d’exploration complémentaire devant un tableau clinique évocateur d’hémorragie méningée","q":"Quelle est la première étape de la stratégie diagnostique devant une céphalée brutale inhabituelle faisant suspecter une hémorragie méningée non traumatique ?","a":"<p>La première étape est de réaliser une <strong>TDM cérébrale sans injection en urgence</strong>.</p>"},{"i":"91ccf3116a07","n":341,"o":"341-4","u":"Diagnostic positif","t":"Connaître la stratégie d’exploration complémentaire devant un tableau clinique évocateur d’hémorragie méningée","q":"Dans quel cas doit-on envisager une ponction lombaire (PL) pour le diagnostic d'hémorragie méningée, et à quel délai optimal par rapport au début des céphalées ?","a":"<p>Une ponction lombaire est envisagée si la <strong>TDM cérébrale est normale</strong> mais que la <strong>suspicion clinique d'hémorragie méningée persiste</strong>. Elle doit être réalisée idéalement <strong>à ≥ 6 heures</strong> du début des céphalées, et de préférence <strong>> 12 heures</strong>, pour optimiser la recherche de xanthochromie.</p>"},{"i":"d45c7b1ecabf","n":341,"o":"341-4","u":"Diagnostic positif","t":"Connaître la stratégie d’exploration complémentaire devant un tableau clinique évocateur d’hémorragie méningée","q":"Quelles sont les contre-indications à la réalisation d'une ponction lombaire face à une suspicion d'hémorragie méningée ?","a":"<p>La ponction lombaire est contre-indiquée en cas de <strong>signes de localisation neurologique</strong> ou si le scanner révèle un <strong>hématome</strong> ou une <strong>hydrocéphalie avec effet de masse</strong>, en raison du risque d'engagement.</p>"},{"i":"0d87dee40efd","n":341,"o":"341-5","u":"Examens complémentaires","t":"Connaître les signes évocateurs d’hémorragie méningée au scanner cérébral sans injection","q":"Quels sont les signes à rechercher au scanner cérébral sans injection qui peuvent orienter vers l'étiologie d'une hémorragie méningée ?","a":"<ul><li>Des <strong>calcifications de la paroi anévrismale</strong> (plus rare) peuvent évoquer un anévrisme.</li><li>Une <strong>HSA corticale</strong> doit faire suspecter une étiologie non anévrismale, comme une <strong>angiopathie amyloïde</strong>, une <strong>malformation artérioveineuse</strong> (MAV) ou une <strong>thrombose veineuse cérébrale</strong>.</li></ul>"},{"i":"153f6b7f444c","n":341,"o":"341-5","u":"Examens complémentaires","t":"Connaître les signes évocateurs d’hémorragie méningée au scanner cérébral sans injection","q":"Quelles sont les complications d'une hémorragie méningée à rechercher systématiquement dès le scanner cérébral initial ?","a":"<ul><li>L'<strong>hématome intraparenchymateux associé</strong>.</li><li>L'<strong>hémorragie intraventriculaire</strong>.</li><li>L'<strong>hydrocéphalie aiguë</strong>, révélée par une dilatation ventriculaire.</li></ul>"},{"i":"237205f252b2","n":341,"o":"341-5","u":"Examens complémentaires","t":"Connaître les signes évocateurs d’hémorragie méningée au scanner cérébral sans injection","q":"Quelles sont les localisations typiques de l'hyperdensité au scanner cérébral sans injection en cas d'hémorragie méningée ?","a":"<ul><li>Les <strong>citernes de la base</strong></li><li>La <strong>vallée sylvienne</strong> (scissure latérale)</li><li>La <strong>scissure interhémisphérique</strong> (longitudinale)</li><li>Les <strong>sillons corticaux</strong></li></ul>"},{"i":"4342eb573a29","n":341,"o":"341-5","u":"Examens complémentaires","t":"Connaître les signes évocateurs d’hémorragie méningée au scanner cérébral sans injection","q":"Quelle est la sensibilité du scanner cérébral sans injection pour le diagnostic d'hémorragie méningée à J1 et son évolution dans le temps ?","a":"<p>La sensibilité est de <strong>95% à J1</strong>. L'hyperdensité régresse progressivement en intensité et disparaît généralement en <strong>5 à 8 jours</strong>.</p>"},{"i":"64fe988e81a2","n":341,"o":"341-5","u":"Examens complémentaires","t":"Connaître les signes évocateurs d’hémorragie méningée au scanner cérébral sans injection","q":"Une TDM cérébrale normale peut-elle éliminer formellement une hémorragie méningée ?","a":"<p>Non, une TDM cérébrale normale <strong>n'élimine pas</strong> formellement une hémorragie méningée. En cas de forte suspicion clinique, elle impose la réalisation d'une <strong>ponction lombaire</strong> (PL) ou d'une <strong>IRM</strong>.</p>"},{"i":"6c28496ef423","n":341,"o":"341-5","u":"Examens complémentaires","t":"Connaître les signes évocateurs d’hémorragie méningée au scanner cérébral sans injection","q":"Quel est le signe direct d'une hémorragie méningée au scanner cérébral sans injection ?","a":"<p>Le signe direct est une <strong>hyperdensité spontanée des espaces sous-arachnoïdiens</strong>.</p>"},{"i":"2c0e59d10f8e","n":341,"o":"341-6","u":"Examens complémentaires","t":"Connaître les caractéristiques du liquide céphalo-rachidien dans l’hémorragie méningée","q":"Dans quel contexte clinique réalise-t-on une ponction lombaire pour le diagnostic d'hémorragie méningée non traumatique ?","a":"<p>Une ponction lombaire est réalisée pour le diagnostic d'hémorragie méningée non traumatique lorsque la <strong>TDM est normale mais la suspicion clinique d'hémorragie méningée non traumatique persiste</strong>. Elle n'est <strong>jamais réalisée d'emblée</strong>.</p>"},{"i":"3c9a83b7dc86","n":341,"o":"341-6","u":"Examens complémentaires","t":"Connaître les caractéristiques du liquide céphalo-rachidien dans l’hémorragie méningée","q":"Qu'est-ce que la xanthochromie du liquide céphalo-rachidien et quelle est sa signification en cas de suspicion d'hémorragie méningée ?","a":"<p>La <strong>xanthochromie</strong> est la coloration jaune du surnageant du liquide céphalo-rachidien (après centrifugation). Elle est due à la présence de pigments sanguins (<strong>bilirubine, oxyhémoglobine</strong>). Sa détection par <strong>spectrophotométrie</strong> est plus sensible et spécifique que l'analyse visuelle. Elle est présente dans <strong>100% des cas d'HSA si la ponction lombaire est réalisée entre 12 heures et 14 jours</strong> après l'événement, témoignant d'une hémorragie ancienne et non d'une ponction traumatique où le surnageant resterait clair.</p>"},{"i":"70a3da20205a","n":341,"o":"341-6","u":"Examens complémentaires","t":"Connaître les caractéristiques du liquide céphalo-rachidien dans l’hémorragie méningée","q":"Quels sont les critères permettant de distinguer à l'examen macroscopique une hémorragie méningée des suites d'une hémorragie sous-arachnoïdienne (HSA) d'une ponction lombaire traumatique ?","a":"<ul><li><strong>Couleur du liquide</strong> : Dans l'HSA, le liquide est <strong>uniformément rouge/rosé dans les 3 tubes</strong>. En cas de ponction traumatique, il est de moins en moins rouge au cours du recueil.</li><li><strong>Coagulabilité</strong> : Le liquide est <strong>incoagulable</strong> dans l'HSA, coagulable en cas de ponction traumatique.</li></ul>"},{"i":"a8a56af73778","n":341,"o":"341-6","u":"Examens complémentaires","t":"Connaître les caractéristiques du liquide céphalo-rachidien dans l’hémorragie méningée","q":"Jusqu'à quand la ponction lombaire reste-t-elle un examen fiable pour exclure une hémorragie sous-arachnoïdienne (HSA) ?","a":"<p>La ponction lombaire pour exclure une hémorragie sous-arachnoïdienne (HSA) est fiable tant que le prélèvement est réalisé <strong>dans les 14 jours</strong> suivant l'événement. <strong>Au-delà de 14 jours, la sensibilité du LCS chute</strong> et une ponction lombaire normale ne permet plus d'exclure formellement une HSA.</p>"},{"i":"de7633a30dca","n":341,"o":"341-6","u":"Examens complémentaires","t":"Connaître les caractéristiques du liquide céphalo-rachidien dans l’hémorragie méningée","q":"Quelles sont les caractéristiques cytologiques et biochimiques du liquide céphalo-rachidien en cas d'hémorragie sous-arachnoïdienne (HSA) ?","a":"<ul><li><strong>Cytologie</strong> : Présence de <strong>globules rouges abondants</strong> avec un rapport GR/GB &gt; 10³. On peut retrouver secondairement une leucocytose lymphocytaire et des sidérophages.</li><li><strong>Biochimie</strong> : La <strong>glycorachie est normale</strong> et on observe une <strong>hyperprotéinorachie</strong>.</li></ul>"},{"i":"6668fa7f7f0c","n":341,"o":"341-7","u":"Contenu multimédia","t":"Tomodensitométrie d’une hémorragie méningée sous-arachnoïdienne","q":"Quel est le signe pivot du diagnostic de l'hémorragie méningée non traumatique à la TDM spontanée ?","a":"<p>Le signe pivot est l'<strong>hyperdensité spontanée des espaces sous-arachnoïdiens</strong>.</p>"},{"i":"7988aec87203","n":341,"o":"341-7","u":"Contenu multimédia","t":"Tomodensitométrie d’une hémorragie méningée sous-arachnoïdienne","q":"Quels sont les différentes localisations de l'hyperdensité spontanée à rechercher à la TDM en cas d'hémorragie sous-arachnoïdienne ?","a":"<ul><li><strong>Hyperdensité spontanée des citernes de la base</strong> (interpédonculaire, pré-pontique, ambiantes).</li><li>Comblement des <strong>vallées sylviennes</strong> et de la <strong>scissure interhémisphérique</strong>.</li><li>Comblement des <strong>sillons corticaux</strong> avec effacement du dessin normal des circonvolutions.</li><li>Aspect en « <strong>moulage</strong> » du polygone de Willis en cas de saignement massif.</li></ul>"},{"i":"adc59613bbab","n":341,"o":"341-7","u":"Contenu multimédia","t":"Tomodensitométrie d’une hémorragie méningée sous-arachnoïdienne","q":"Quel est le piège classique lié au délai de réalisation de la TDM dans le diagnostic d'hémorragie méningée non traumatique ?","a":"<p>L'<strong>hyperdensité spontanée disparaît en 5 à 8 jours</strong>. Une TDM réalisée au-delà de J7-J8 peut être faussement normale, nécessitant une <strong>ponction lombaire</strong> si la suspicion clinique persiste.</p>"},{"i":"b923245b0c98","n":341,"o":"341-7","u":"Contenu multimédia","t":"Tomodensitométrie d’une hémorragie méningée sous-arachnoïdienne","q":"Quelles complications de l'hémorragie sous-arachnoïdienne peuvent être associées et visibles à la TDM ?","a":"<ul><li><strong>Hématome intra-parenchymateux</strong> (se présentant comme une hyperdensité intra-cérébrale associée).</li><li><strong>Hémorragie intra-ventriculaire</strong>.</li><li><strong>Hydrocéphalie aiguë</strong>.</li></ul>"},{"i":"068522aa1682","n":341,"o":"341-9","u":"Identifier une urgence","t":"Connaître l’urgence d’une hémorragie méningée","q":"Quelle est l'urgence d'une hémorragie méningée non traumatique (HSA) ?","a":"<p>L'hémorragie méningée non traumatique (HSA) est une <strong>urgence vitale absolue</strong>, avec une mortalité globale de <strong>40 à 50%</strong>, dont 10 à 20% de décès avant l'arrivée à l'hôpital.</p>"},{"i":"25fa08edd5a0","n":341,"o":"341-9","u":"Identifier une urgence","t":"Connaître l’urgence d’une hémorragie méningée","q":"Comment doit se décliner l'urgence diagnostique et étiologique face à une hémorragie méningée non traumatique (HSA) ?","a":"<ul><li><strong>Diagnostic immédiat</strong> par un <strong>scanner cérébral sans injection</strong> en première intention et sans délai.</li><li><strong>Étiologique immédiat</strong> (dès l'HSA confirmée) par une <strong>angioTDM</strong>.</li></ul>"},{"i":"2c3203b5575c","n":341,"o":"341-9","u":"Identifier une urgence","t":"Connaître l’urgence d’une hémorragie méningée","q":"Quel est l'objectif thérapeutique urgent en cas d'hémorragie méningée non traumatique (HSA) et pourquoi ?","a":"<p>L'objectif thérapeutique est d'exclure l'anévrisme vasculaire dans les <strong>moins de 48 heures</strong> (par <strong>clippage</strong> ou <strong>embolisation</strong>) afin de <strong>prévenir la récidive hémorragique</strong>, dont l'incidence est maximale dans les 24 premières heures.</p>"},{"i":"56bcde11be54","n":341,"o":"341-9","u":"Identifier une urgence","t":"Connaître l’urgence d’une hémorragie méningée","q":"Quelle est la conduite à tenir immédiate en cas de suspicion d'hémorragie méningée non traumatique (HSA) ?","a":"<p>Toute suspicion d'HSA impose un <strong>transfert urgent et médicalisé</strong> vers un centre disposant :</p><ul><li>D'une unité de neurochirurgie</li><li>De neuroradiologie interventionnelle</li><li>De neuroréanimation</li></ul>"}]};